INSERT INTO `courses` VALUES (1,'Generative AI Foundations: From Basics to Real-World Applications','generative-ai-foundations-from-basics-to-real-world-applications-1','Learn what Generative AI is, how it works, and how to use it effectively. Explore tools like ChatGPT and DALL·E, prompt engineering, and key applications across industries.',5,1,'general','active','beginner','english',0,0,0,0,0,0,NULL,NULL,NULL,NULL,NULL,NULL,'<p><strong>Generative AI</strong> is transforming how we create, learn, and work. This beginner-friendly course demystifies the technology behind AI models that generate text, images, audio, and code. You\'ll start with simple definitions and real-world examples like ChatGPT, DALL·E, and Midjourney, then dive into how these systems learn from massive datasets using neural networks and transformers.</p><p>We\'ll explore the different types of generative AI—text, image, audio, code, and video—and examine their practical applications in education, business, healthcare, software development, and content creation. You\'ll also learn about the benefits (speed, creativity, productivity) and the risks (bias, misinformation, deepfakes, privacy).</p><p>A key skill you\'ll develop is <strong>prompt engineering</strong>: crafting clear instructions to get the best results from AI. Through examples of good vs. bad prompts, you\'ll gain hands-on insight. By the end, you\'ll understand why generative AI is a pivotal technology shaping our future.</p>','[\"No prior AI knowledge required\",\"Basic computer literacy\",\"Interest in learning about AI tools\",\"Access to a web browser\"]','[\"Define generative AI and distinguish it from traditional AI\",\"Explain how generative AI learns from data using neural networks and transformers\",\"Identify at least three types of generative AI (text, image, audio, code, video)\",\"List real-world applications in education, business, healthcare, and content creation\",\"Recognize key advantages and limitations, including ethical risks\",\"Apply basic prompt engineering techniques to improve AI outputs\"]',NULL,'[5]',0,'2026-05-21 07:12:35','2026-05-21 07:12:35',NULL);

