INSERT INTO `lessons` VALUES (1,'PART A: Grammar Knowledge',1,NULL,NULL,'practice_test',NULL,'all_authenticated','0:30:0',30,21,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'15 questions, 2 points each',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(2,'Test 2: Speaking and Communication Assessment',1,NULL,NULL,'practice_test',NULL,'all_authenticated','0:12:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Test 2: Speaking and Communication Assessment\n\nPurpose:\nEvaluates verbal clarity, professional tone, ability to organize thoughts and deliver information concisely in a live spoken setting.\n\nWho Should Take It:\nAll candidates. All roles. Especially critical for client-facing, sales, and leadership roles.\n\nSkills / Competencies Assessed:\nVerbal clarity, pronunciation and articulation, professional tone, logical organization of ideas, ability to explain complex information simply, active listening, poise under pressure.\n\nFormat:\nLive structured oral assessment conducted by interviewer.\nThree components: structured introduction (2 min), scenario response (3 min), impromptu explanation (3 min).\nTotal: 10–12 minutes.\n\nEvaluator Instructions:\nRead each prompt aloud to the candidate.\nScore each criterion in real time.\nAllow the candidate 15–20 seconds to gather thoughts before responding.\n\nScoring Rubric (60 points total):\n- Clarity of speech: 10\n- Professional tone: 10\n- Logical organization: 10\n- Conciseness: 10\n- Vocabulary and grammar: 10\n- Poise and composure: 10\n\nPass Threshold:\n42/60 and no single criterion below 5/10.\nBorderline:\n36–41/60.\nFail:\nBelow 36/60 or any single criterion 3/10 or below.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-08 00:29:09','2026-04-08 00:29:09'),(3,'Computer Literacy Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:20:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nVerifies that the candidate has the foundational computer skills required to work in a remote, AI-native, technology-dependent environment. Defrilex operates entirely with cloud-based tools, CRM systems, video conferencing, and digital workflows. A team member who cannot navigate basic computer tasks creates operational drag.\n\nWho Should Take It:\nAll candidates. All roles. All levels.\n\nSkills / Competencies Assessed:\nFile management, email proficiency, cloud tool navigation (Google Workspace / Microsoft 365), browser competency, basic spreadsheet skills, video conferencing tool usage, keyboard shortcuts, file format knowledge, troubleshooting basics.\n\nFormat:\n20 multiple-choice and scenario-based questions.\n20 minutes.\n\nScoring Rubric:\n- Multiple-choice (20 Q): 60 points (3 points per correct answer, no partial credit)\n- Pass Threshold: 42/60 (70%)\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nResult Triggers:\n- Pass (42+): Advance\n- Borderline (36-41): Advance with tech coaching flag for non-technical roles only\n- Fail (<36): Do not advance\n\nTraining / Remediation Link:\nDefrilex Digital Workplace Foundations module. Cloud tools onboarding track. Computer literacy remediation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-16 07:15:55','2026-04-24 01:51:18'),(4,'AI Literacy Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:20:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nVerifies that the candidate understands what AI tools are, how they work at a practical level, when to use them appropriately, what their limitations are, and how AI fits into a professional work environment. Defrilex is an AI-native company where every team member is expected to use AI as a daily productivity tool.\n\nWho Should Take It:\nAll candidates. All roles. All levels.\n\nSkills / Competencies Assessed:\nUnderstanding of what AI is and is not, practical AI tool usage (prompt writing, output evaluation), awareness of AI limitations and risks, understanding of when AI is appropriate vs. when human judgment is required, AI ethics awareness.\n\nFormat:\n15 questions: 10 multiple-choice, 3 scenario-based judgment, 2 short-answer.\n20 minutes.\n\nScoring Rubric:\n- Multiple-choice (10 Q): 30 points (3 points per correct answer)\n- Scenario judgment (3 Q): 18 points (6 points each)\n- Short-answer (2 Q): 12 points (6 points each)\n- Pass Threshold: 42/60 (70%)\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nResult Triggers:\n- Pass (42+): Advance\n- Borderline (36-41): Advance with mandatory AI literacy onboarding module\n- Fail (<36): Do not advance\n\nTraining / Remediation Link:\nDefrilex AI Tool Training module. Prompt engineering basics. AI-assisted workflow training for role-specific applications.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-16 07:19:48','2026-04-24 01:51:18'),(5,'Cybersecurity Literacy Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:15:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nVerifies that the candidate understands basic cybersecurity practices required to protect Defrilex, its clients, and their data. Defrilex serves regulated industries (healthcare, government, fintech) where data breaches create legal liability, client loss, and reputational damage.\n\nWho Should Take It:\nAll candidates. All roles. All levels.\n\nSkills / Competencies Assessed:\nPhishing recognition, password management, data handling awareness, secure communication practices, incident reporting, device security, social engineering awareness.\n\nFormat:\n15 questions: 10 multiple-choice, 5 scenario-based judgment.\n15 minutes.\n\nScoring Rubric:\n- Multiple-choice (10 Q): 30 points (3 points per correct answer)\n- Scenario judgment (5 Q): 30 points (6 points each)\n- Pass Threshold: 42/60 (70%)\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nResult Triggers:\n- Pass (42+): Advance\n- Borderline (36-41): Advance with mandatory cybersecurity onboarding module before any system access\n- Fail (<36): Must complete cybersecurity training and retest before advancing\n\nTraining / Remediation Link:\nDefrilex Cybersecurity Foundations module. Phishing awareness training. Data handling compliance training.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-16 08:09:54','2026-04-24 01:51:18'),(6,'Remote Work Literacy Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:15:0',48,34,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nVerifies that the candidate understands how to work effectively and professionally in a fully remote environment. Defrilex operates as a distributed company. Remote discipline is not optional - it is a core competency.\n\nWho Should Take It:\nAll candidates. All roles.\n\nSkills / Competencies Assessed:\nSelf-management, time management, asynchronous communication, workspace setup, proactive reporting, availability discipline, remote meeting etiquette, accountability without supervision.\n\nFormat:\n12 scenario-based judgment questions.\n15 minutes.\n\nScoring Rubric:\n- Scenario judgment (12 Q): 48 points (4 points per correct answer, no partial credit)\n- Pass Threshold: 34/48 (70%)\n- Borderline / Review Needed: 28-33/48\n- Fail: below 28/48\n\nResult Triggers:\n- Pass (34+): Advance\n- Borderline (28-33): Advance with remote work readiness discussion in onboarding\n- Fail (<28): Do not advance\n\nTraining / Remediation Link:\nDefrilex Remote Work Standards module. Asynchronous communication training. Self-management and accountability training.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-16 08:11:39','2026-04-24 01:51:18'),(7,'Professionalism, Judgment, and Accountability Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:20:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether the candidate demonstrates the values and judgment Defrilex requires: accountability, integrity, ownership, dignity, and excellence. This test reveals character and decision-making patterns that predict cultural fit at Defrilex.\n\nWho Should Take It:\nAll candidates. All roles. All levels. This test should carry significant weight in the overall hiring decision.\n\nSkills / Competencies Assessed:\nAccountability under pressure, ethical judgment, ownership behavior, professional decision-making, conflict handling, truthfulness, client-first orientation, ability to admit mistakes.\n\nFormat:\n12 scenario-based judgment questions + 2 short-answer reflections.\n20 minutes.\n\nScoring Rubric:\n- Scenario judgment (12 Q): 48 points (4 points each; full credit for best answer, 2 for acceptable, 0 for poor)\n- Short-answer (2 Q): 12 points (6 points each; honesty, self-awareness, specificity, alignment with accountability/ownership values)\n- Pass Threshold: 42/60 (70%). Must score at least 7/12 on short-answer section.\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nResult Triggers:\n- Pass (42+): Strong culture signal. Advance.\n- Borderline (36-41): Proceed with culture interview focus on accountability and ownership.\n- Fail (<36): Serious concern. Do not advance unless other signals are overwhelmingly strong.\n\nTraining / Remediation Link:\nDefrilex Values and Culture onboarding module. Accountability and ownership standards. Professional judgment development.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-16 08:13:31','2026-04-24 01:51:18'),(8,'Attention to Detail Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:20:0',50,35,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nMeasures the candidate\'s ability to catch errors, inconsistencies, and inaccuracies in data, text, and processes. In regulated-industry services, a single overlooked error can create compliance violations, client trust damage, or financial loss.\n\nWho Should Take It:\nAll candidates. All roles. Especially weighted for operations, QA, finance, and client-facing roles.\n\nSkills / Competencies Assessed:\nError detection in text, numerical accuracy, pattern recognition, consistency checking, data validation, process compliance awareness.\n\nFormat:\n4 exercises: data error detection, text proofreading, email inconsistency check, process checklist validation.\n20 minutes.\n\nScoring Rubric:\n- Exercise 1: Data Errors (5 items): 15 pts (3 points per correctly identified error)\n- Exercise 2: Email Problems (5 items): 10 pts (2 points per correctly identified problem)\n- Exercise 3: Checklist Issues (5 items): 15 pts (3 points per correctly identified issue)\n- Exercise 4: Number Discrepancies (5 items): 10 pts (2 points per correctly identified discrepancy)\n- Pass Threshold: 35/50 (70%)\n- Borderline / Review Needed: 25-34/50\n- Fail: below 25/50\n\nGrading Answer Keys (for reviewers):\n\nExercise 1:\n1. \'Frnech\' should be \'French\' (Row 2)\n2. Maria Santos double-booked — 9:00 AM and 9:30 AM on same date (Rows 1 and 4); scheduling conflict / insufficient gap\n3. Invalid date \'13/17/2026\' — no 13th month (Row 5)\n4. \'Confrimed\' should be \'Confirmed\' (Row 6)\n5. Maria Santos overlap / double-booking creates scheduling conflict (tie to rows 1 and 4)\n\nExercise 2:\n1. Subject says \'Great Quarter\' but results are mixed (below target on closes, retention down)\n2. \'Outstanding quarter all around\' contradicts the data (missed client target, retention declined)\n3. \'Lead\' should be \'led\' (grammar — team lead by Marcus)\n4. Retention declined from 94% to 91% but email frames everything as positive — tone/intellectual honesty\n5. Closing 12 vs 15 target — miss not adequately acknowledged\n\nExercise 3:\n1. Missing: BAA/compliance documentation step (healthcare) before service begins\n2. Out of order: Kickoff call (Step 4) should come before interpreter scheduling (Step 3)\n3. Missing: Interpreter vetting / language pair confirmation for client needs\n4. Missing: SLA/quality standards documentation shared with client\n5. Out of order: Welcome packet (Step 6) should come before or with kickoff (Step 4), not only after scheduling\n\nExercise 4:\n1. Total sessions: summary says 847, data says 874\n2. Language pairs: summary says 12, data says 14\n3. QA score: summary says 94.2%, data says 92.4%\n4. Spanish called highest-volume at 312, but Haitian Creole had 318\n5. QA improvement overstated — actual Feb 91.8% to Mar 92.4%, not to 94.2%\n\nResult Triggers:\n- Pass (35+): Advance\n- Borderline (25-34): Advance with coaching flag; weight for detail-critical roles\n- Fail (<25): Do not advance for detail-critical roles unless other signals are very strong\n\nTraining / Remediation Link:\nDefrilex Quality Assurance Standards module. Data verification practices. Process compliance training.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-16 08:21:10','2026-04-24 01:51:18'),(9,'Typing Speed and Accuracy Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:5:0',100,1,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nVerifies that the candidate can type at the speed and accuracy level required for productive remote work, CRM documentation, real-time note-taking, and communication. Slow or inaccurate typing creates operational drag in every role.\n\nWho Should Take It:\nAll candidates. All roles. Higher thresholds for BPO/customer support, operations, and data entry roles.\n\nSkills / Competencies Assessed:\nTyping speed (words per minute), typing accuracy (error rate), ability to type from dictation or source material.\n\nFormat:\nTimed typing test: 3-minute passage transcription + 2-minute dictation typing exercise.\nTotal: 5 minutes active typing.\n\nScoring Method (manual evaluator scoring):\n- Measure WPM and accuracy for both exercises.\n- Record final decision as Pass / Borderline / Fail according to thresholds below.\n\nThresholds:\n- Standard roles (pass): 40+ WPM and 95%+ accuracy\n- BPO/support/data roles (pass): 55+ WPM and 97%+ accuracy\n- Borderline: 35-39 WPM or 92-94% accuracy\n- Fail: below 35 WPM or below 92% accuracy\n\nResult Triggers:\n- Pass: Advance\n- Borderline: Advance with improvement expectation; not eligible for typing-intensive roles\n- Fail: Do not advance for BPO/support/data roles; may advance for non-typing-intensive roles if close to threshold\n\nEvaluator Notes:\n- What Success Looks Like: Candidate types fluently at or above threshold speed with minimal errors in both transcription and dictation.\n- What Failure Looks Like: Candidate types below threshold, makes frequent errors, or cannot keep pace with moderate dictation.\n- Red Flags: below 25 WPM, below 90% accuracy, inability to type from dictation.\n\nTraining / Remediation Link:\nTyping improvement resources. Daily typing practice recommendation. Speed and accuracy benchmarking.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-17 07:02:29','2026-04-24 01:51:18'),(10,'Interpreter Readiness Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:30:0',70,49,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether an interpreter candidate has the professional judgment, ethical awareness, terminology handling ability, and real-time decision-making skills required for regulated-industry interpretation. This is not a language proficiency test - it tests interpreter competency.\n\nWho Should Take It:\nAll interpreter candidates (OPI, VRI, on-site). All language pairs. All tiers.\n\nSkills / Competencies Assessed:\nInterpreter ethics and code of conduct, medical/legal/financial terminology handling, impartiality and boundary management, accuracy under pressure, cultural competency, professional behavior in sensitive settings.\n\nFormat:\n10 scenario-based judgment questions + 1 practical terminology exercise + 1 role-play description.\n30 minutes.\n\nScoring Rubric:\n- Scenario judgment (10 Q): 50 points (5 points each; best: 5, acceptable: 3, poor: 0)\n- Terminology exercise: 10 points (2 points per relevant term with valid rationale, up to 10; deduct if generic or not cardiology-relevant)\n- Role-play introduction script: 10 points (self-intro 2, role clarification 3, confidentiality 3, instructions to participants 2)\n- Pass Threshold: 49/70 (70%). Must score at least 35/50 on scenario section.\n- Borderline / Review Needed: 42-48/70\n- Fail: below 42/70\n\nResult Triggers:\n- Pass (49+): Advance to language proficiency testing and QA scoring\n- Borderline (42-48): Advance with interpreter ethics/standards coaching flag\n- Fail (<42): Do not advance - interpreter readiness fundamentals not met\n\nTraining / Remediation Link:\nDefrilex Interpreter Standards and Ethics module. Medical/Legal terminology preparation training. Session management and boundary training.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-17 07:36:24','2026-04-24 01:51:18'),(11,'Sales Readiness Assessment (SDR / Account Manager)',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:30:0',70,49,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether a sales candidate has the prospecting judgment, discovery skill, qualification discipline, and consultative selling instincts required to sell trust-first into regulated industries. Defrilex does not sell on price or volume - it sells on trust, compliance, and quality.\n\nWho Should Take It:\nSDR candidates, Account Manager candidates, BD candidates. All sales levels.\n\nSkills / Competencies Assessed:\nProspecting judgment, ICP understanding, discovery questioning, qualification discipline (knowing when NOT to pursue), objection handling, consultative vs. transactional selling, CRM discipline, pipeline management awareness.\n\nFormat:\n8 scenario-based judgment questions + 1 discovery call role-play outline + 1 prospecting prioritization exercise.\n30 minutes.\n\nScoring Rubric:\n- Scenario judgment (8 Q): 40 points (5 points each)\n- Discovery call outline: 15 points (opening/agenda 3, question quality and insight 7, close/next steps 5)\n- Prospecting prioritization: 15 points (correct ranking logic 8, quality of reasoning 7; deduct if non-ICP prospect ranked highest)\n- Pass Threshold: 49/70 (70%)\n- Borderline / Review Needed: 42-48/70\n- Fail: below 42/70\n\nSuggested prioritization reference (evaluators): C (government, RFI - active buyer), A (healthcare, contract expiring, engaged), E (legal, quality pain), D (fintech ICP but cold), B (not ICP - lowest).\n\nResult Triggers:\n- Pass (49+): Advance to culture interview\n- Borderline (42-48): Advance with sales training deep-dive planned\n- Fail (<42): Do not advance\n\nTraining / Remediation Link:\nDefrilex Sales Operating System. Consultative selling methodology. ICP and qualification training. Discovery call framework. CRM discipline standards.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-18 05:39:55','2026-04-24 01:51:18'),(12,'Marketing Readiness Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:30:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether a marketing candidate can produce trust-building, compliance-aware content and strategy for regulated-industry buyers. Defrilex\'s marketing must reduce perceived buyer risk, not just generate awareness.\n\nWho Should Take It:\nAll marketing candidates: content, demand gen, brand, digital marketing.\n\nSkills / Competencies Assessed:\nTrust-first messaging, regulated-industry awareness, content strategy, brand voice discipline, audience understanding, conversion-oriented writing, channel strategy.\n\nFormat:\n6 judgment questions + 2 practical exercises (messaging rewrite, content brief).\n30 minutes.\n\nScoring Rubric:\n- Judgment questions (6 Q): 30 points (5 points each)\n- Messaging rewrite: 15 points (trust-first positioning 5, audience relevance 5, professional quality 5)\n- Content brief: 15 points (audience clarity 3, key message strength 3, point quality 4, CTA relevance 2, SEO awareness 3)\n- Pass Threshold: 42/60 (70%)\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nResult Triggers:\n- Pass (42+): Advance\n- Borderline (36-41): Advance with regulated-industry marketing training\n- Fail (<36): Do not advance\n\nTraining / Remediation Link:\nDefrilex Marketing Operating System. Trust-first messaging framework. Regulated-industry content strategy. Brand voice guidelines.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-18 05:42:04','2026-04-24 01:51:18'),(13,'Operations Readiness Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:25:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether an operations candidate has the process discipline, problem-solving ability, SLA awareness, and operational judgment required to manage service delivery at Defrilex. Operations is where promises become reality.\n\nWho Should Take It:\nAll operations candidates: operations coordinators, operations managers, service delivery specialists, scheduling coordinators.\n\nSkills / Competencies Assessed:\nProcess discipline, SLA management, capacity planning awareness, incident handling, cross-functional coordination, root-cause analysis, documentation rigor, prioritization under pressure.\n\nFormat:\n8 scenario-based judgment questions + 1 practical exercise (incident response).\n25 minutes.\n\nScoring Rubric:\n- Scenario judgment (8 Q): 40 points (5 points each)\n- Incident report: 20 points (factual accuracy 4, root cause analysis 4, resolution steps 3, client communication plan 3, preventive measures 3, ownership assignment 3)\n- Pass Threshold: 42/60 (70%). Must score 14+ on incident report.\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nResult Triggers:\n- Pass (42+): Advance\n- Borderline (36-41): Advance with operations standards training\n- Fail (<36): Do not advance\n\nTraining / Remediation Link:\nDefrilex Operations OS. SLA management training. Incident response protocol. Root-cause analysis methodology.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-18 06:14:41','2026-04-24 01:51:18'),(14,'Leadership and Management Readiness Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:25:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether a management candidate can lead with clarity, accountability, data-driven decision-making, and people development discipline that Defrilex requires. Bad management is the single most expensive people failure.\n\nWho Should Take It:\nAll candidates for team lead, manager, director, or leadership positions.\n\nSkills / Competencies Assessed:\nAccountability enforcement, feedback delivery, performance management, delegation, coaching, data-driven decision-making, conflict resolution, strategic prioritization, culture stewardship.\n\nFormat:\n8 scenario-based leadership judgment questions + 2 short-answer reflections.\n25 minutes.\n\nScoring Rubric:\n- Scenario judgment (8 Q): 40 points (5 points each)\n- Short-answer (2 Q): 20 points (10 points each; specificity, accountability demonstrated, management maturity, alignment with Defrilex standards)\n- Pass Threshold: 42/60 (70%). Must score 12+ on short answers.\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60 - strong concern for management readiness\n\nResult Triggers:\n- Pass (42+): Advance to culture interview with Fritz\n- Borderline (36-41): Advance with management development plan\n- Fail (<36): Do not advance for management roles; may be suitable for IC roles\n\nTraining / Remediation Link:\nDefrilex Manager Operating Standards. Feedback delivery (SBI model). Performance management system. 1:1 framework. Escalation protocol.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-18 06:17:10','2026-04-24 01:51:18'),(15,'Finance Readiness Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:25:0',60,42,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether a finance candidate has the analytical accuracy, judgment, and operational finance understanding required to support Defrilex\'s financial operations, billing accuracy, margin management, and financial reporting.\n\nWho Should Take It:\nAll finance candidates: finance analysts, billing specialists, controllers, financial operations staff.\n\nSkills / Competencies Assessed:\nFinancial accuracy, billing operations, gross margin analysis, revenue recognition awareness, budget variance analysis, financial reporting, data integrity, compliance awareness.\n\nFormat:\n8 knowledge/judgment questions + 1 practical exercise (billing discrepancy analysis).\n25 minutes.\n\nScoring Rubric:\n- Knowledge/judgment (8 Q): 40 points (5 points each)\n- Billing discrepancy analysis: 20 points (each discrepancy identified up to 16 pts at 4 each; resolution quality 4 pts)\n- Pass Threshold: 42/60 (70%). Must score 14+ on billing analysis.\n- Borderline / Review Needed: 36-41/60\n- Fail: below 36/60\n\nGrading answer key (billing exercise):\n1. VRI billed at $67 instead of contracted $75 - underbilling of $8 x 45 = $360 revenue loss.\n2. Correct VRI line should be 45 x $75 = $3,375, not $3,000 - confirms $375 underbilling on VRI line.\n3. Total invoice should be $9,900 + $3,375 = $13,275 vs $12,900 - $375 revenue leakage vs correct contract.\n4. Gross margin: OPI ($55-$28)/$55 = 49%; VRI ($75-$38)/$75 = 49.3% - both healthy; confirm vs target.\n5. Payment matched incorrect invoice - need corrected invoice and collection of $375 difference (or reconcile per policy).\n\nResult Triggers:\n- Pass (42+): Advance\n- Borderline (36-41): Advance with finance onboarding focus on billing operations\n- Fail (<36): Do not advance\n\nTraining / Remediation Link:\nDefrilex Finance Operating System. Billing operations training. Revenue recognition fundamentals. Financial integrity standards.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-18 06:18:30','2026-04-24 01:51:18'),(16,'IT and Cybersecurity Readiness Assessment',NULL,NULL,NULL,'practice_test',NULL,'all_authenticated','0:30:0',70,49,9999,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Purpose:\nEvaluates whether an IT/cybersecurity candidate has the technical knowledge, incident response judgment, and compliance awareness required to protect Defrilex\'s infrastructure and its regulated-industry clients\' data.\n\nWho Should Take It:\nAll IT and cybersecurity candidates: IT support, systems administrators, security analysts, compliance-focused IT roles.\n\nSkills / Competencies Assessed:\nNetwork security fundamentals, incident response, compliance framework awareness (HIPAA, SOC 2), access control management, vulnerability management, encryption understanding, security policy enforcement, vendor security assessment.\n\nFormat:\nPART A: 10 technical knowledge questions. PART B: 3 scenario-based judgment questions. Practical exercise: incident response plan.\n30 minutes.\n\nScoring Rubric:\n- Technical knowledge (10 Q): 30 points (3 points each)\n- Scenario judgment (3 Q): 18 points (6 points each)\n- Incident response plan: 22 points (containment 4, investigation 4, notification 4, remediation 4, prevention 4, order/completeness 2)\n- Pass Threshold: 49/70 (70%). Must score 15+ on incident response plan.\n- Borderline / Review Needed: 42-48/70\n- Fail: below 42/70\n\nResult Triggers:\n- Pass (49+): Advance\n- Borderline (42-48): Advance with compliance-focused onboarding\n- Fail (<42): Do not advance\n\nTraining / Remediation Link:\nDefrilex Cybersecurity and Compliance module. HIPAA compliance training. Incident response protocol. Vendor security assessment training. SOC 2 preparation.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-04-18 06:19:39','2026-04-24 01:51:18'),(17,'What Is Generative AI?',5,1,1,'text','text','all_authenticated','00:05:00',NULL,NULL,NULL,NULL,'<p><strong>Generative AI</strong> refers to artificial intelligence systems that can create new content—such as text, images, music, or code—based on patterns learned from existing data. Unlike traditional AI, which typically analyzes or classifies data (e.g., identifying spam emails or predicting house prices), generative AI produces original outputs that mimic human creativity.</p><p>Key differences include:</p><ul><li><strong>Purpose:</strong> Traditional AI focuses on prediction or classification; generative AI focuses on creation.</li><li><strong>Output:</strong> Traditional AI outputs labels, numbers, or categories; generative AI outputs new text, images, or audio.</li><li><strong>Learning:</strong> Generative models learn the underlying distribution of training data to generate novel samples, while traditional models learn decision boundaries or mappings.</li></ul><p>For example, a traditional AI might tell you whether an email is spam, while a generative AI like ChatGPT can write a poem or answer a question in a conversational style. This creative capability is what makes generative AI so exciting and transformative.</p><h5>Key points</h5><ul><li>Generative AI creates new content, unlike traditional AI which analyzes or classifies.</li><li>It learns patterns from data to produce original outputs.</li><li>Examples include text generation, image creation, and music composition.</li><li>Generative AI mimics human creativity but relies on statistical patterns.</li></ul><p><strong>Practice:</strong> Write a short paragraph explaining generative AI to a friend who has never heard of it. Use a simple analogy, like comparing it to an artist learning from examples.</p>',NULL,NULL,NULL,0,1,'<p><strong>Generative AI</strong> refers to artificial intelligence systems that can create new content—such as text, images, music, or code—based on patterns learned from existing data. Unlike traditional AI, which typically analyzes or classifies data (e.g., identifying spam emails or predicting house prices), generative AI produces original outputs that mimic human creativity.</p><p>Key differences include:</p><ul><li><strong>Purpose:</strong> Traditional AI focuses on prediction or classification; generative AI focuses on creation.</li><li><strong>Output:</strong> Traditional AI outputs labels, numbers, or categories; generative AI outputs new text, images, or audio.</li><li><strong>Learning:</strong> Generative models learn the underlying distribution of training data to generate novel samples, while traditional models learn decision boundaries or mappings.</li></ul><p>For example, a traditional AI might tell you whether an email is spam, while a generative AI like ChatGPT can write a poem or answer a question in a conversational style. This creative capability is what makes generative AI so exciting and transformative.</p><h5>Key points</h5><ul><li>Generative AI creates new content, unlike traditional AI which analyzes or classifies.</li><li>It learns patterns from data to produce original outputs.</li><li>Examples include text generation, image creation, and music composition.</li><li>Generative AI mimics human creativity but relies on statistical patterns.</li></ul><p><strong>Practice:</strong> Write a short paragraph explaining generative AI to a friend who has never heard of it. Use a simple analogy, like comparing it to an artist learning from examples.</p>','Generative AI refers to artificial intelligence systems that can create new content—such as text, images, music, or code—based on patterns learned from existing data. Unlike traditional AI, which typi...','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[\"Generative AI creates new content, unlike traditional AI which analyzes or classifies.\", \"It learns patterns from data to produce original outputs.\", \"Examples include text generation, image creation, and music composition.\", \"Generative AI mimics human creativity but relies on statistical patterns.\"]',1,'2026-05-21 07:25:38','2026-05-21 07:25:38'),(18,'How Generative AI Differs from Traditional AI',5,1,1,'text','audio','all_authenticated','00:05:00',NULL,NULL,NULL,NULL,'<p>To truly understand generative AI, it helps to compare it with traditional AI. Traditional AI systems are often <strong>discriminative</strong>—they learn to distinguish between different types of data. For instance, a spam filter learns to separate spam from legitimate emails. In contrast, generative AI models learn the underlying patterns of data so well that they can produce new, similar data.</p><p>Here are the main differences:</p><ul><li><strong>Task:</strong> Traditional AI answers \'What is this?\' (classification) or \'How much?\' (regression). Generative AI answers \'Create something new like this.\'</li><li><strong>Data usage:</strong> Traditional AI uses labeled data for supervised learning. Generative AI often uses unlabeled data and learns the data distribution.</li><li><strong>Examples:</strong> Traditional AI: facial recognition, fraud detection. Generative AI: ChatGPT (text), DALL·E (images), Midjourney (art).</li></ul><p>Think of it this way: traditional AI is like a detective who identifies clues; generative AI is like an artist who paints a new scene based on memories of real landscapes. Both are valuable, but they serve different purposes.</p><h5>Key points</h5><ul><li>Traditional AI is discriminative; generative AI is creative.</li><li>Traditional AI classifies or predicts; generative AI produces new content.</li><li>Generative AI learns data distributions, often without labels.</li><li>Real-world examples: ChatGPT, DALL·E, Midjourney.</li></ul><p><strong>Practice:</strong> List three tasks you do daily that could be automated by traditional AI (e.g., sorting emails) and three that could be enhanced by generative AI (e.g., drafting a message).</p>',NULL,NULL,NULL,0,2,'<p>To truly understand generative AI, it helps to compare it with traditional AI. Traditional AI systems are often <strong>discriminative</strong>—they learn to distinguish between different types of data. For instance, a spam filter learns to separate spam from legitimate emails. In contrast, generative AI models learn the underlying patterns of data so well that they can produce new, similar data.</p><p>Here are the main differences:</p><ul><li><strong>Task:</strong> Traditional AI answers \'What is this?\' (classification) or \'How much?\' (regression). Generative AI answers \'Create something new like this.\'</li><li><strong>Data usage:</strong> Traditional AI uses labeled data for supervised learning. Generative AI often uses unlabeled data and learns the data distribution.</li><li><strong>Examples:</strong> Traditional AI: facial recognition, fraud detection. Generative AI: ChatGPT (text), DALL·E (images), Midjourney (art).</li></ul><p>Think of it this way: traditional AI is like a detective who identifies clues; generative AI is like an artist who paints a new scene based on memories of real landscapes. Both are valuable, but they serve different purposes.</p><h5>Key points</h5><ul><li>Traditional AI is discriminative; generative AI is creative.</li><li>Traditional AI classifies or predicts; generative AI produces new content.</li><li>Generative AI learns data distributions, often without labels.</li><li>Real-world examples: ChatGPT, DALL·E, Midjourney.</li></ul><p><strong>Practice:</strong> List three tasks you do daily that could be automated by traditional AI (e.g., sorting emails) and three that could be enhanced by generative AI (e.g., drafting a message).</p>','To truly understand generative AI, it helps to compare it with traditional AI. Traditional AI systems are often discriminative—they learn to distinguish between different types of data. For instance,...','Welcome back! In this lesson, we explore how generative AI is different from the AI you might already know. Traditional AI is like a skilled detective—it identifies patterns and makes decisions. Generative AI, on the other hand, is like a creative artist—it learns from examples and then creates something entirely new. Think of a spam filter versus ChatGPT. One sorts, the other writes. This distinction is key to understanding why generative AI is so powerful. By the end of this lesson, you\'ll be able to spot the difference and appreciate the unique capabilities of each type. Let\'s dive in!',NULL,NULL,NULL,NULL,NULL,'/storage/personalized_audio/db6d97f3-d2d2-4606-9d95-6b4d97873f33.wav','ready','gemini_tts','[\"Traditional AI is discriminative; generative AI is creative.\", \"Traditional AI classifies or predicts; generative AI produces new content.\", \"Generative AI learns data distributions, often without labels.\", \"Real-world examples: ChatGPT, DALL·E, Midjourney.\"]',1,'2026-05-21 07:25:38','2026-05-21 07:26:03'),(19,'Generative AI in Action: ChatGPT, DALL·E, and Midjourney',5,1,2,'html5','video','all_authenticated','00:05:00',NULL,NULL,NULL,'/storage/personalized_video/lesson-19-100e2ecb-4a22-4866-96f7-a9183d60665c.mp4','<p class=\"text-muted\"><i class=\"fi fi-rr-spinner\"></i> AI presenter video is being generated… Page will update when ready.</p><p>Generative AI is already transforming how we work, create, and communicate. Three standout examples are <strong>ChatGPT</strong>, <strong>DALL·E</strong>, and <strong>Midjourney</strong>. Each demonstrates a different creative capability.</p><ul><li><strong>ChatGPT:</strong> A conversational AI that generates human-like text. It can answer questions, write essays, compose emails, and even code. It\'s built on a large language model (LLM) trained on vast amounts of text from the internet.</li><li><strong>DALL·E:</strong> Developed by OpenAI, DALL·E generates images from text descriptions. For example, typing \'a cat wearing a top hat\' produces a unique image matching that description. It combines language understanding with image generation.</li><li><strong>Midjourney:</strong> An AI art generator that creates stunning, artistic images from text prompts. It\'s popular among designers and artists for its aesthetic quality and style versatility.</li></ul><p>These tools are used in marketing, education, entertainment, and more. They show how generative AI can augment human creativity, not replace it. As you explore these applications, think about how they might help in your own projects.</p><h5>Key points</h5><ul><li>ChatGPT generates text for conversations, writing, and coding.</li><li>DALL·E creates images from text descriptions.</li><li>Midjourney produces artistic images with a unique style.</li><li>These tools are used in marketing, education, and creative fields.</li><li>Generative AI augments human creativity, not replaces it.</li></ul><p><strong>Practice:</strong> Use ChatGPT (or a similar free tool) to generate a short story about a robot learning to paint. Then, use DALL·E or Midjourney to create an image of that robot. Share your results and reflect on the experience.</p>',NULL,NULL,'https://files2.heygen.ai/aws_pacific/avatar_tmp/692ed713725f4d0fb87d05805a8e5602/555b799949414ab6a28f4c25a1bfa298.jpeg?Expires=1779918027&Signature=I9gwm6FAvP5yB4d5X85urZ50RMdAy6ZCM25SM7c1~xq8uh2iAykUWIATEDbLRe4FYo8xZmFlngP~kNxxnVuws7-thvSofV5WlRnasXYcywE2EFKPUsilXWkA4sP~Mbk8zxCTtCe7aLkIWgaLSWi5Q1-rUSM7c7jySBeGehK6-qJiWtAf6DH4j9NvhiFFZxe6RqfDn-guevmTAJW1j6cHjbRUIf0XxAPX4cpVKJhyx08Bl67IV48U75CyRJY8gkspP06waPx508GiWMZqxyZqoMpDD7lOO2xZ0lhjZ~F0rdfVywEjuNzBZ5Xfc9oxgZG20BwYxIVa0mI7IaP6x7QgAw__&Key-Pair-Id=K38HBHX5LX3X2H',0,3,'<p>Generative AI is already transforming how we work, create, and communicate. Three standout examples are <strong>ChatGPT</strong>, <strong>DALL·E</strong>, and <strong>Midjourney</strong>. Each demonstrates a different creative capability.</p><ul><li><strong>ChatGPT:</strong> A conversational AI that generates human-like text. It can answer questions, write essays, compose emails, and even code. It\'s built on a large language model (LLM) trained on vast amounts of text from the internet.</li><li><strong>DALL·E:</strong> Developed by OpenAI, DALL·E generates images from text descriptions. For example, typing \'a cat wearing a top hat\' produces a unique image matching that description. It combines language understanding with image generation.</li><li><strong>Midjourney:</strong> An AI art generator that creates stunning, artistic images from text prompts. It\'s popular among designers and artists for its aesthetic quality and style versatility.</li></ul><p>These tools are used in marketing, education, entertainment, and more. They show how generative AI can augment human creativity, not replace it. As you explore these applications, think about how they might help in your own projects.</p><h5>Key points</h5><ul><li>ChatGPT generates text for conversations, writing, and coding.</li><li>DALL·E creates images from text descriptions.</li><li>Midjourney produces artistic images with a unique style.</li><li>These tools are used in marketing, education, and creative fields.</li><li>Generative AI augments human creativity, not replaces it.</li></ul><p><strong>Practice:</strong> Use ChatGPT (or a similar free tool) to generate a short story about a robot learning to paint. Then, use DALL·E or Midjourney to create an image of that robot. Share your results and reflect on the experience.</p>','Generative AI is already transforming how we work, create, and communicate. Three standout examples are ChatGPT, DALL·E, and Midjourney. Each demonstrates a different creative capability.ChatGPT: A co...','Hello! In this lesson, we\'ll see generative AI in action with three amazing tools: ChatGPT, DALL·E, and Midjourney. ChatGPT is like a super-smart writing assistant—it can answer questions, write stories, and even help with homework. DALL·E turns your words into pictures, so if you imagine a \'panda riding a bicycle,\' it creates that image. Midjourney is an artist\'s dream, producing beautiful, creative artwork from simple prompts. These tools are already changing how we work and play. By the end of this lesson, you\'ll understand how each one works and how you can start using them today. Let\'s explore!','heygen','ready','555b799949414ab6a28f4c25a1bfa298',NULL,'2026-05-21 07:25:39',NULL,NULL,NULL,'[\"ChatGPT generates text for conversations, writing, and coding.\", \"DALL·E creates images from text descriptions.\", \"Midjourney produces artistic images with a unique style.\", \"These tools are used in marketing, education, and creative fields.\", \"Generative AI augments human creativity, not replaces it.\"]',1,'2026-05-21 07:25:39','2026-05-21 07:40:38'),(20,'What is Generative AI?',5,1,3,'html5','video','all_authenticated','00:05:00',NULL,NULL,NULL,'/storage/personalized_video/lesson-20-523e5c11-49e5-4ce3-a601-d71ed248776c.mp4','<p><strong>Generative AI</strong> is a type of artificial intelligence that creates new content—such as text, images, music, or code—based on patterns it learns from existing data. Unlike traditional AI, which typically analyzes or classifies data (e.g., sorting emails as spam or not), generative AI produces original outputs that mimic human creativity.</p><p>For example, a traditional AI might predict the next word in a sentence, while a generative AI like ChatGPT can write an entire essay. Similarly, DALL·E generates images from text descriptions, and Midjourney creates artistic visuals. These tools learn from vast datasets and use complex models to generate novel results.</p><p>Key differences include:</p><ul><li><strong>Purpose:</strong> Traditional AI analyzes; generative AI creates.</li><li><strong>Output:</strong> Traditional AI gives labels or predictions; generative AI produces new data.</li><li><strong>Examples:</strong> Spam filters vs. ChatGPT, image classifiers vs. DALL·E.</li></ul><p>Generative AI is transforming industries by enabling personalized content, rapid prototyping, and creative assistance. Understanding its basics is the first step to leveraging its power.</p><h5>Key points</h5><ul><li>Generative AI creates new content from learned patterns.</li><li>It differs from traditional AI, which analyzes or classifies.</li><li>Real-world examples include ChatGPT, DALL·E, and Midjourney.</li><li>Outputs can be text, images, music, or code.</li><li>It relies on large datasets and complex models.</li></ul><p><strong>Practice:</strong> Think of a task you do daily (e.g., writing an email). Describe how a generative AI tool could help you create it from scratch. Write 2-3 sentences.</p>',NULL,NULL,'https://files2.heygen.ai/aws_pacific/avatar_tmp/692ed713725f4d0fb87d05805a8e5602/5ac82d80ef3c44adab83cd97bea4dc29.jpeg?Expires=1779918084&Signature=SOeg5kuhwTcTAt2-Nx71y3TIkANQCDzkQjK~Svtd8V8CP7kUehSKivJLmJ9HbbIbbwTrMV6o0rPHknMbHay75uYqko80hNGyUcYB068KfoeZSWBJX0XdiR4PYBHA2siUyJSIFwzkXzrPt0lJa71m0Rbe6lI~ZkPBOdsZIxhIpCiLjbWOBjmgYB1HY5zxVNJ3YQK62cYzi3wpAuaYgB2ld0oWFlqZ3bigrPdoJzBkCJy2poJGTKu4mRAagy9ZL0tcOwC~QGLDzxn1UtmsNczvoe2Mop~C7P4hMnaaUgkPAKsUnJge4gNen5bNQxFipegqdKX1bxMxzRAbuVERXYNQaA__&Key-Pair-Id=K38HBHX5LX3X2H',0,4,'<p><strong>Generative AI</strong> is a type of artificial intelligence that creates new content—such as text, images, music, or code—based on patterns it learns from existing data. Unlike traditional AI, which typically analyzes or classifies data (e.g., sorting emails as spam or not), generative AI produces original outputs that mimic human creativity.</p><p>For example, a traditional AI might predict the next word in a sentence, while a generative AI like ChatGPT can write an entire essay. Similarly, DALL·E generates images from text descriptions, and Midjourney creates artistic visuals. These tools learn from vast datasets and use complex models to generate novel results.</p><p>Key differences include:</p><ul><li><strong>Purpose:</strong> Traditional AI analyzes; generative AI creates.</li><li><strong>Output:</strong> Traditional AI gives labels or predictions; generative AI produces new data.</li><li><strong>Examples:</strong> Spam filters vs. ChatGPT, image classifiers vs. DALL·E.</li></ul><p>Generative AI is transforming industries by enabling personalized content, rapid prototyping, and creative assistance. Understanding its basics is the first step to leveraging its power.</p><h5>Key points</h5><ul><li>Generative AI creates new content from learned patterns.</li><li>It differs from traditional AI, which analyzes or classifies.</li><li>Real-world examples include ChatGPT, DALL·E, and Midjourney.</li><li>Outputs can be text, images, music, or code.</li><li>It relies on large datasets and complex models.</li></ul><p><strong>Practice:</strong> Think of a task you do daily (e.g., writing an email). Describe how a generative AI tool could help you create it from scratch. Write 2-3 sentences.</p>','Generative AI is a type of artificial intelligence that creates new content—such as text, images, music, or code—based on patterns it learns from existing data. Unlike traditional AI, which typically...','Welcome! Today we explore generative AI—a technology that creates, not just analyzes. Imagine an AI that writes stories or paints pictures. That\'s generative AI. Unlike traditional AI, which sorts data, generative AI produces new content. Think of ChatGPT for text, DALL·E for images, or Midjourney for art. These tools learn from millions of examples and generate original outputs. In this lesson, we\'ll define generative AI and see how it\'s different. Let\'s dive in and unlock your creativity!','heygen','ready','5ac82d80ef3c44adab83cd97bea4dc29',NULL,'2026-05-21 07:37:11',NULL,NULL,NULL,'[\"Generative AI creates new content from learned patterns.\", \"It differs from traditional AI, which analyzes or classifies.\", \"Real-world examples include ChatGPT, DALL·E, and Midjourney.\", \"Outputs can be text, images, music, or code.\", \"It relies on large datasets and complex models.\"]',1,'2026-05-21 07:37:11','2026-05-21 07:41:35'),(21,'How Generative AI Works: A Simple Overview',5,1,3,'text','video','all_authenticated','00:05:00',NULL,NULL,NULL,NULL,'<p class=\"text-muted heygen-pending-notice\"><i class=\"fi fi-rr-spinner\"></i> AI presenter video is being generated… Page will update when ready.</p><p>At its core, generative AI uses <strong>neural networks</strong> trained on massive datasets. These networks learn patterns, relationships, and structures in the data. For instance, a text model learns grammar, facts, and writing styles from billions of sentences. An image model learns shapes, colors, and objects from millions of pictures.</p><p>The training process involves two key steps:</p><ul><li><strong>Training:</strong> The model processes data and adjusts its internal parameters to minimize errors in predicting or generating outputs.</li><li><strong>Generation:</strong> Given a prompt (e.g., \"a cat in a spacesuit\"), the model uses its learned patterns to create a new, coherent output.</li></ul><p>Popular architectures include <strong>transformers</strong> (for text) and <strong>diffusion models</strong> (for images). Transformers power ChatGPT by predicting the next word in a sequence. Diffusion models, used by DALL·E, start with random noise and gradually refine it into a clear image.</p><p>This process is computationally intensive, but recent advances have made it accessible via cloud APIs. Understanding this helps you appreciate both the capabilities and limitations of generative AI.</p><h5>Key points</h5><ul><li>Generative AI uses neural networks trained on large datasets.</li><li>Training adjusts parameters to learn patterns.</li><li>Generation creates outputs from prompts.</li><li>Transformers are used for text; diffusion models for images.</li><li>Computational power is high but accessible via APIs.</li></ul><p><strong>Practice:</strong> Write a short prompt (e.g., &#039;a sunny beach at sunset&#039;) and imagine what a generative AI might create. Describe the output in 2-3 sentences.</p>',NULL,NULL,NULL,0,5,'<p>At its core, generative AI uses <strong>neural networks</strong> trained on massive datasets. These networks learn patterns, relationships, and structures in the data. For instance, a text model learns grammar, facts, and writing styles from billions of sentences. An image model learns shapes, colors, and objects from millions of pictures.</p><p>The training process involves two key steps:</p><ul><li><strong>Training:</strong> The model processes data and adjusts its internal parameters to minimize errors in predicting or generating outputs.</li><li><strong>Generation:</strong> Given a prompt (e.g., \"a cat in a spacesuit\"), the model uses its learned patterns to create a new, coherent output.</li></ul><p>Popular architectures include <strong>transformers</strong> (for text) and <strong>diffusion models</strong> (for images). Transformers power ChatGPT by predicting the next word in a sequence. Diffusion models, used by DALL·E, start with random noise and gradually refine it into a clear image.</p><p>This process is computationally intensive, but recent advances have made it accessible via cloud APIs. Understanding this helps you appreciate both the capabilities and limitations of generative AI.</p><h5>Key points</h5><ul><li>Generative AI uses neural networks trained on large datasets.</li><li>Training adjusts parameters to learn patterns.</li><li>Generation creates outputs from prompts.</li><li>Transformers are used for text; diffusion models for images.</li><li>Computational power is high but accessible via APIs.</li></ul><p><strong>Practice:</strong> Write a short prompt (e.g., &#039;a sunny beach at sunset&#039;) and imagine what a generative AI might create. Describe the output in 2-3 sentences.</p>','At its core, generative AI uses neural networks trained on massive datasets. These networks learn patterns, relationships, and structures in the data. For instance, a text model learns grammar, facts,...','Hello! Let\'s peek under the hood of generative AI. It\'s all about neural networks learning from tons of data. Think of it like teaching a child by showing thousands of examples. The model finds patterns—like how words fit together or what a cat looks like. Then, when you give it a prompt, it creates something new. For text, we use transformers; for images, diffusion models. It\'s amazing but needs lots of computing. Ready to learn more? Let\'s go!','heygen','pending','c0d49fe355e047c2b2ba88c9ffdced6b',NULL,'2026-05-21 07:37:12',NULL,NULL,NULL,'[\"Generative AI uses neural networks trained on large datasets.\", \"Training adjusts parameters to learn patterns.\", \"Generation creates outputs from prompts.\", \"Transformers are used for text; diffusion models for images.\", \"Computational power is high but accessible via APIs.\"]',1,'2026-05-21 07:37:12','2026-05-21 07:37:12'),(22,'Real-World Examples: ChatGPT, DALL·E, and Midjourney',5,1,3,'text','text','all_authenticated','00:05:00',NULL,NULL,NULL,NULL,'<p>Generative AI is already part of our daily lives. Here are three standout examples:</p><ul><li><strong>ChatGPT:</strong> A conversational AI that writes essays, answers questions, codes, and more. It\'s used for customer support, tutoring, and content creation.</li><li><strong>DALL·E:</strong> Creates images from text descriptions. For instance, \'a penguin wearing a top hat\' generates a unique image. Artists and designers use it for inspiration.</li><li><strong>Midjourney:</strong> Produces artistic, high-quality visuals. It\'s popular for concept art, marketing, and social media graphics.</li></ul><p>These tools share a common foundation: they learn from vast datasets and generate novel outputs. However, they differ in focus—ChatGPT excels at text, while DALL·E and Midjourney specialize in images. Each has unique strengths, such as Midjourney\'s artistic style or ChatGPT\'s conversational depth.</p><p>Exploring these examples shows the breadth of generative AI and sparks ideas for your own projects.</p><h5>Key points</h5><ul><li>ChatGPT generates text for conversations, writing, and coding.</li><li>DALL·E creates images from text prompts.</li><li>Midjourney produces artistic visuals.</li><li>All learn from large datasets but specialize differently.</li><li>They are used in creative, professional, and educational contexts.</li></ul><p><strong>Practice:</strong> Choose one tool (ChatGPT, DALL·E, or Midjourney). Write a prompt you would give it and describe the expected output. Share your idea in 2-3 sentences.</p>',NULL,NULL,NULL,0,6,'<p>Generative AI is already part of our daily lives. Here are three standout examples:</p><ul><li><strong>ChatGPT:</strong> A conversational AI that writes essays, answers questions, codes, and more. It\'s used for customer support, tutoring, and content creation.</li><li><strong>DALL·E:</strong> Creates images from text descriptions. For instance, \'a penguin wearing a top hat\' generates a unique image. Artists and designers use it for inspiration.</li><li><strong>Midjourney:</strong> Produces artistic, high-quality visuals. It\'s popular for concept art, marketing, and social media graphics.</li></ul><p>These tools share a common foundation: they learn from vast datasets and generate novel outputs. However, they differ in focus—ChatGPT excels at text, while DALL·E and Midjourney specialize in images. Each has unique strengths, such as Midjourney\'s artistic style or ChatGPT\'s conversational depth.</p><p>Exploring these examples shows the breadth of generative AI and sparks ideas for your own projects.</p><h5>Key points</h5><ul><li>ChatGPT generates text for conversations, writing, and coding.</li><li>DALL·E creates images from text prompts.</li><li>Midjourney produces artistic visuals.</li><li>All learn from large datasets but specialize differently.</li><li>They are used in creative, professional, and educational contexts.</li></ul><p><strong>Practice:</strong> Choose one tool (ChatGPT, DALL·E, or Midjourney). Write a prompt you would give it and describe the expected output. Share your idea in 2-3 sentences.</p>','Generative AI is already part of our daily lives. Here are three standout examples:ChatGPT: A conversational AI that writes essays, answers questions, codes, and more. It\'s used for customer support,...','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[\"ChatGPT generates text for conversations, writing, and coding.\", \"DALL·E creates images from text prompts.\", \"Midjourney produces artistic visuals.\", \"All learn from large datasets but specialize differently.\", \"They are used in creative, professional, and educational contexts.\"]',1,'2026-05-21 07:37:12','2026-05-21 07:37:12'),(23,'Getting Started with Text Generation',5,1,4,'html5','video','all_authenticated','00:05:00',NULL,NULL,NULL,'/storage/personalized_video/lesson-23-0453b426-0392-49b2-ba44-eabf5f71fe30.mp4','<p>Text generation is one of the most accessible forms of generative AI. Tools like ChatGPT, Claude, and Gemini allow you to create content by simply typing a prompt. Here\'s how to start:</p><ul><li><strong>Choose a platform:</strong> Sign up for ChatGPT (free tier) or another text AI.</li><li><strong>Craft a clear prompt:</strong> Be specific. Instead of \'write a story,\' try \'write a 100-word story about a robot learning to dance.\'</li><li><strong>Iterate:</strong> Refine your prompt based on the output. Add details or change the tone.</li><li><strong>Use cases:</strong> Draft emails, brainstorm ideas, summarize articles, or write code snippets.</li></ul><p>Remember, generative AI is a collaborator. It can produce drafts, but you should review and edit for accuracy and style. Practice with different prompts to see how the model responds. Over time, you\'ll learn to guide it effectively.</p><p>Text generation saves time and sparks creativity. Start small and experiment!</p><h5>Key points</h5><ul><li>Text generation tools like ChatGPT are easy to use.</li><li>Clear, specific prompts yield better results.</li><li>Iterate on prompts to refine outputs.</li><li>Use cases include writing, brainstorming, and coding.</li><li>Always review and edit AI-generated content.</li></ul><p><strong>Practice:</strong> Use a free text AI (e.g., ChatGPT) to write a short paragraph about a topic you enjoy. Then, revise the prompt to change the tone (e.g., from formal to funny). Note the differences.</p>',NULL,NULL,'https://files2.heygen.ai/aws_pacific/avatar_tmp/692ed713725f4d0fb87d05805a8e5602/27cc4d4fce684f37a248906a576ab00b.jpeg?Expires=1779918309&Signature=Rw0XO8ojjx-GGtWy2d-34jWY-IJrXDmGRNVmbixzqhCg6e~2zj2Idc~U43jO0sREIShEZ7w-QabYTSfxVscqRfSqBgO7jJELdzPPWn3aXVhS5G2c8eAzuZL7psgoV9nPbqtjU8jqCtHY9vDTG31XHulwgsVk02ky24YFuje5Jz-7A3yUrz0oaJOP5V4ugdNZ5Bwb0VkfFyAvFWNpZfhVPL3SmAzoLaApJqerYjF6P0LuFo8Y-kE4U1gAcwnsm6WpiKQAi1Dy5RpzCo~UfQbHm5bsZ0hV5T-UnY013ScTwCfNKzm1VUt9VFrtFW1A5ChbOKSqDfAXaU99RtlURdoiAw__&Key-Pair-Id=K38HBHX5LX3X2H',0,7,'<p>Text generation is one of the most accessible forms of generative AI. Tools like ChatGPT, Claude, and Gemini allow you to create content by simply typing a prompt. Here\'s how to start:</p><ul><li><strong>Choose a platform:</strong> Sign up for ChatGPT (free tier) or another text AI.</li><li><strong>Craft a clear prompt:</strong> Be specific. Instead of \'write a story,\' try \'write a 100-word story about a robot learning to dance.\'</li><li><strong>Iterate:</strong> Refine your prompt based on the output. Add details or change the tone.</li><li><strong>Use cases:</strong> Draft emails, brainstorm ideas, summarize articles, or write code snippets.</li></ul><p>Remember, generative AI is a collaborator. It can produce drafts, but you should review and edit for accuracy and style. Practice with different prompts to see how the model responds. Over time, you\'ll learn to guide it effectively.</p><p>Text generation saves time and sparks creativity. Start small and experiment!</p><h5>Key points</h5><ul><li>Text generation tools like ChatGPT are easy to use.</li><li>Clear, specific prompts yield better results.</li><li>Iterate on prompts to refine outputs.</li><li>Use cases include writing, brainstorming, and coding.</li><li>Always review and edit AI-generated content.</li></ul><p><strong>Practice:</strong> Use a free text AI (e.g., ChatGPT) to write a short paragraph about a topic you enjoy. Then, revise the prompt to change the tone (e.g., from formal to funny). Note the differences.</p>','Text generation is one of the most accessible forms of generative AI. Tools like ChatGPT, Claude, and Gemini allow you to create content by simply typing a prompt. Here\'s how to start:Choose a platfor...','Hey there! Ready to create with text? Let\'s start with ChatGPT. First, pick a platform—many are free. Then, write a clear prompt. Instead of \'write something,\' try \'write a poem about a rainy day.\' See how the output changes? You can tweak your prompt to get exactly what you want. Use it for emails, stories, or even code. Remember, you\'re the editor—AI is your helper. Practice makes perfect. Let\'s generate something amazing together!','heygen','ready','27cc4d4fce684f37a248906a576ab00b',NULL,'2026-05-21 07:37:13',NULL,NULL,NULL,'[\"Text generation tools like ChatGPT are easy to use.\", \"Clear, specific prompts yield better results.\", \"Iterate on prompts to refine outputs.\", \"Use cases include writing, brainstorming, and coding.\", \"Always review and edit AI-generated content.\"]',1,'2026-05-21 07:37:13','2026-05-21 07:45:19'),(24,'Exploring Image Generation with DALL·E and Midjourney',5,1,4,'text','audio','all_authenticated','00:05:00',NULL,NULL,NULL,NULL,'<p>Image generation tools like DALL·E and Midjourney turn your words into visuals. Here\'s how to get started:</p><ul><li><strong>DALL·E:</strong> Accessible via OpenAI\'s platform. Enter a description like \'a futuristic city at sunset\' and it generates multiple images.</li><li><strong>Midjourney:</strong> Works through Discord. Use commands like \'/imagine\' followed by your prompt. It produces artistic, high-resolution images.</li><li><strong>Tips for prompts:</strong> Include style (e.g., \'watercolor,\' \'photorealistic\'), lighting, and composition. For example, \'a cat in a spacesuit, digital art, vibrant colors.\'</li><li><strong>Iterate:</strong> Adjust your prompt to refine results. Add or remove details to match your vision.</li></ul><p>These tools are used for concept art, marketing, social media, and personal projects. They democratize creativity—you don\'t need drawing skills to create stunning visuals. Experiment with different styles and subjects to see the range of possibilities.</p><p>Remember, generated images may have limitations (e.g., odd hands). Use them as starting points or inspiration.</p><h5>Key points</h5><ul><li>DALL·E and Midjourney generate images from text prompts.</li><li>Prompts should include style, lighting, and details.</li><li>Iterate on prompts to improve results.</li><li>Use cases include art, marketing, and personal projects.</li><li>Generated images may need refinement.</li></ul><p><strong>Practice:</strong> Create an image prompt for DALL·E or Midjourney (e.g., &#039;a dragon reading a book, fantasy art&#039;). Describe what you hope the image will look like in 2-3 sentences.</p>',NULL,NULL,NULL,0,8,'<p>Image generation tools like DALL·E and Midjourney turn your words into visuals. Here\'s how to get started:</p><ul><li><strong>DALL·E:</strong> Accessible via OpenAI\'s platform. Enter a description like \'a futuristic city at sunset\' and it generates multiple images.</li><li><strong>Midjourney:</strong> Works through Discord. Use commands like \'/imagine\' followed by your prompt. It produces artistic, high-resolution images.</li><li><strong>Tips for prompts:</strong> Include style (e.g., \'watercolor,\' \'photorealistic\'), lighting, and composition. For example, \'a cat in a spacesuit, digital art, vibrant colors.\'</li><li><strong>Iterate:</strong> Adjust your prompt to refine results. Add or remove details to match your vision.</li></ul><p>These tools are used for concept art, marketing, social media, and personal projects. They democratize creativity—you don\'t need drawing skills to create stunning visuals. Experiment with different styles and subjects to see the range of possibilities.</p><p>Remember, generated images may have limitations (e.g., odd hands). Use them as starting points or inspiration.</p><h5>Key points</h5><ul><li>DALL·E and Midjourney generate images from text prompts.</li><li>Prompts should include style, lighting, and details.</li><li>Iterate on prompts to improve results.</li><li>Use cases include art, marketing, and personal projects.</li><li>Generated images may need refinement.</li></ul><p><strong>Practice:</strong> Create an image prompt for DALL·E or Midjourney (e.g., &#039;a dragon reading a book, fantasy art&#039;). Describe what you hope the image will look like in 2-3 sentences.</p>','Image generation tools like DALL·E and Midjourney turn your words into visuals. Here\'s how to get started:DALL·E: Accessible via OpenAI\'s platform. Enter a description like \'a futuristic city at sunse...','Welcome to image generation! Tools like DALL·E and Midjourney let you paint with words. Describe a scene—like \'a castle in the clouds\'—and watch it come to life. For best results, add style details: \'watercolor\' or \'cyberpunk.\' Try different prompts and see what works. Use these images for projects or just for fun. It\'s like magic, but you\'re the wizard. Let\'s create some art together!',NULL,NULL,NULL,NULL,NULL,NULL,'pending',NULL,'[\"DALL·E and Midjourney generate images from text prompts.\", \"Prompts should include style, lighting, and details.\", \"Iterate on prompts to improve results.\", \"Use cases include art, marketing, and personal projects.\", \"Generated images may need refinement.\"]',1,'2026-05-21 07:37:13','2026-05-21 07:37:13'),(25,'Ethical Considerations and Best Practices',5,1,4,'text','text','all_authenticated','00:05:00',NULL,NULL,NULL,NULL,'<p>Generative AI is powerful, but it comes with responsibilities. Here are key ethical considerations and best practices:</p><ul><li><strong>Bias:</strong> Models learn from internet data, which may contain biases. Always review outputs for fairness and inclusivity.</li><li><strong>Misinformation:</strong> AI can generate convincing but false content. Verify facts, especially for news or academic work.</li><li><strong>Copyright:</strong> Generated content may resemble existing works. Use it as inspiration, not direct copying.</li><li><strong>Privacy:</strong> Avoid sharing sensitive personal information in prompts.</li><li><strong>Transparency:</strong> Disclose when using AI-generated content, especially in professional or public contexts.</li></ul><p>Best practices include: using AI as a tool, not a replacement for human judgment; citing sources when needed; and staying informed about evolving guidelines. By using generative AI ethically, you maximize its benefits while minimizing risks.</p><p>Remember, you are responsible for the content you create and share. Use AI to enhance, not replace, your own creativity and critical thinking.</p><h5>Key points</h5><ul><li>Be aware of bias in AI outputs.</li><li>Verify AI-generated information for accuracy.</li><li>Respect copyright and avoid plagiarism.</li><li>Protect your privacy when using AI tools.</li><li>Disclose AI use when appropriate.</li></ul><p><strong>Practice:</strong> Reflect on a potential ethical issue with generative AI (e.g., deepfakes). Write 2-3 sentences on how you would address it as a user.</p>',NULL,NULL,NULL,0,9,'<p>Generative AI is powerful, but it comes with responsibilities. Here are key ethical considerations and best practices:</p><ul><li><strong>Bias:</strong> Models learn from internet data, which may contain biases. Always review outputs for fairness and inclusivity.</li><li><strong>Misinformation:</strong> AI can generate convincing but false content. Verify facts, especially for news or academic work.</li><li><strong>Copyright:</strong> Generated content may resemble existing works. Use it as inspiration, not direct copying.</li><li><strong>Privacy:</strong> Avoid sharing sensitive personal information in prompts.</li><li><strong>Transparency:</strong> Disclose when using AI-generated content, especially in professional or public contexts.</li></ul><p>Best practices include: using AI as a tool, not a replacement for human judgment; citing sources when needed; and staying informed about evolving guidelines. By using generative AI ethically, you maximize its benefits while minimizing risks.</p><p>Remember, you are responsible for the content you create and share. Use AI to enhance, not replace, your own creativity and critical thinking.</p><h5>Key points</h5><ul><li>Be aware of bias in AI outputs.</li><li>Verify AI-generated information for accuracy.</li><li>Respect copyright and avoid plagiarism.</li><li>Protect your privacy when using AI tools.</li><li>Disclose AI use when appropriate.</li></ul><p><strong>Practice:</strong> Reflect on a potential ethical issue with generative AI (e.g., deepfakes). Write 2-3 sentences on how you would address it as a user.</p>','Generative AI is powerful, but it comes with responsibilities. Here are key ethical considerations and best practices:Bias: Models learn from internet data, which may contain biases. Always review out...','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'[\"Be aware of bias in AI outputs.\", \"Verify AI-generated information for accuracy.\", \"Respect copyright and avoid plagiarism.\", \"Protect your privacy when using AI tools.\", \"Disclose AI use when appropriate.\"]',1,'2026-05-21 07:37:13','2026-05-21 07:37:13');

