INSERT INTO `notification_settings` VALUES (1,'edit_email_template',1,NULL,'[\"admin\",\"user\"]','{\"admin\":\"1\",\"user\":\"1\"}','{\"admin\":\"1\",\"user\":\"0\"}','{\"admin\":\"New user registered\",\"user\":\"Registered successfully\"}','{\"admin\":\"New user registered [user_name] \\r\\n<br>User email: <b>[user_email]<\\/b>\",\"user\":\"You have successfully registered with us at [system_name].\"}','New user registration','Get notified when a new user signs up','1693215071','2023-11-02 11:13:07','2023-12-05 01:23:15'),(2,'email_verification',0,NULL,'[\"user\"]','{\"user\":\"0\"}','{\"user\":\"1\"}','{\"user\":\"Email verification code\"}','{\"user\":\"You have received a email verification code. Your verification code is [email_verification_code]\"}','Email verification','It is permanently enabled for student email verification.','1684135777','2023-11-02 11:13:07','2023-11-02 11:13:07'),(3,'forget_password_mail',0,NULL,'[\"user\"]','{\"user\":\"0\"}','{\"user\":\"1\"}','{\"user\":\"Forgot password verification code\"}','{\"user\":\"You have received a email verification code. Your verification code is [system_name][verification_link][minutes]\"}','Forgot password mail','It is permanently enabled for student email verification.','1684145383','2023-11-02 11:13:07','2023-11-02 11:13:07'),(4,'new_device_login_confirmation',0,NULL,'[\"user\"]','{\"user\":\"0\"}','{\"user\":\"1\"}','{\"user\":\"Please confirm your login\"}','{\"user\":\"Have you tried logging in with a different device? Confirm using the verification code. Your verification code is [verification_code]. Remember that you will lose access to your previous device after logging in to the new device <b>[user_agent]<\\/b>.<br> Use the verification code within [minutes] minutes\"}','Account security alert','Send verification code for login from a new device','1684145383','2023-11-02 11:13:07','2023-11-02 11:13:07'),(6,'course_purchase',1,NULL,'[\"admin\",\"student\",\"instructor\"]','{\"admin\":\"1\",\"student\":\"1\",\"instructor\":\"1\"}','{\"admin\":\"0\",\"student\":\"0\",\"instructor\":\"0\"}','{\"admin\":\"A new course has been sold\",\"instructor\":\"A new course has been sold\",\"student\":\"You have purchased a new course\"}','{\"admin\":\"<p>Course title: [course_title]<\\/p><p>Student: [student_name]\\r\\n<\\/p><p>Paid amount: [paid_amount]<\\/p><p>Instructor: [instructor_name]<\\/p>\",\"instructor\":\"Course title: [course_title]\\r\\nStudent: [student_name]\\r\\nPaid amount: [paid_amount]\",\"student\":\"Course title: [course_title]\\r\\nPaid amount: [paid_amount]\\r\\nInstructor: [instructor_name]\"}','Course purchase notification','Stay up-to-date on student course purchases.','1684303456','2023-11-02 11:13:07','2023-11-02 11:13:07'),(7,'course_completion_mail',1,NULL,'[\"student\",\"instructor\"]','{\"student\":\"1\",\"instructor\":\"1\"}','{\"student\":\"0\",\"instructor\":\"0\"}','{\"instructor\":\"Course completion\",\"student\":\"You have completed a new course\"}','{\"instructor\":\"Course completed [course_title]\\r\\nStudent: [student_name]\",\"student\":\"Course: [course_title]\\r\\nInstructor: [instructor_name]\"}','Course completion mail','Stay up to date on student course completion.','1684303457','2023-11-02 11:13:07','2023-11-02 11:13:07'),(8,'certificate_eligibility',1,'certificate','[\"student\",\"instructor\"]','{\"student\":\"1\",\"instructor\":\"1\"}','{\"student\":\"0\",\"instructor\":\"0\"}','{\"instructor\":\"Certificate eligibility\",\"student\":\"certificate eligibility\"}','{\"instructor\":\"Course: [course_title]\\r\\nStudent: [student_name]\\r\\nCertificate link: [certificate_link]\",\"student\":\"Course: [course_title]\\r\\nInstructor: [instructor_name]\\r\\nCertificate link: [certificate_link]\"}','Course eligibility notification','Stay up to date on course certificate eligibility.','1684303460','2023-11-02 11:13:07','2023-11-02 11:13:07'),(9,'offline_payment_suspended_mail',1,'offline_payment','[\"student\"]','{\"student\":\"1\"}','{\"student\":\"0\"}','{\"student\":\"Your payment has been suspended\"}','{\"student\":\"<p>Your offline payment has been <b style=\'color: red;\'>suspended</b> !</p><p>Please provide a valid document of your payment.</p>\"}','Offline payment suspended mail','If students provides fake information, notify them of the suspension','1684303463','2023-11-02 11:13:07','2023-11-02 11:13:07'),(10,'bundle_purchase',1,'course_bundle','[\"admin\",\"student\",\"instructor\"]','{\"admin\":\"1\",\"student\":\"1\",\"instructor\":\"1\"}','{\"admin\":\"0\",\"student\":\"0\",\"instructor\":\"0\"}','{\"admin\":\"A new course bundle has been sold \",\"instructor\":\"A new course bundle has been sold \",\"student\":\"You have purchased a new course bundle test\"}','{\"admin\":\"Course bundle: [bundle_title]\\r\\nStudent: [student_name]\\r\\nInstructor: [instructor_name] \",\"instructor\":\"Course bundle: [bundle_title]\\r\\nStudent: [student_name] \",\"student\":\"Course bundle: [bundle_title]\\r\\nInstructor: [instructor_name] \"}','Course bundle purchase notification','Stay up-to-date on student course bundle purchases.','1684303467','2023-11-02 11:13:07','2023-11-02 11:13:07'),(13,'add_new_user_as_affiliator',0,'affiliate_course','[\"affiliator\"]','{\"affiliator\":\"0\"}','{\"affiliator\":\"1\"}','{\"affiliator\":\"Congratulation ! You are assigned as an affiliator\"}','{\"affiliator\":\"You are assigned as a website Affiliator.\\r\\nWebsite: [website_link]\\r\\n<br>\\r\\nPassword: [password]\"}','New user added as affiliator','Send account information to the new user','1684135777','2023-11-02 11:13:07','2023-11-02 11:13:07'),(14,'affiliator_approval_notification',1,'affiliate_course','[\"affiliator\"]','{\"affiliator\":\"1\"}','{\"affiliator\":\"0\"}','{\"affiliator\":\"Congratulations! Your affiliate request has been approved\"}','{\"affiliator\":\"Congratulations! Your affiliate request has been approved\"}','Affiliate approval notification','Send affiliate approval mail to the user account','1684303472','2023-11-02 11:13:07','2023-11-02 11:13:07'),(15,'affiliator_request_cancellation',1,'affiliate_course','[\"affiliator\"]','{\"affiliator\":\"1\"}','{\"affiliator\":\"0\"}','{\"affiliator\":\"Sorry ! Your request has been currently refused\"}','{\"affiliator\":\"Sorry ! Your request has been currently refused.\"}','Affiliator request cancellation','Send mail, when you cancel the affiliation request','1684303473','2023-11-02 11:13:07','2023-11-02 11:13:07'),(16,'affiliation_amount_withdrawal_request',1,'affiliate_course','[\"admin\",\"affiliator\"]','{\"admin\":\"1\",\"affiliator\":\"1\"}','{\"admin\":\"0\",\"affiliator\":\"0\"}','{\"admin\":\"New money withdrawal request\",\"affiliator\":\"New money withdrawal request\"}','{\"admin\":\"New money withdrawal request by [\'user_name] [amount]\",\"affiliator\":\"Your Withdrawal request of [amount] has been sent to authority\"}','Affiliation money withdrawal request','Send mail, when the users request the withdrawal of money','1684303476','2023-11-02 11:13:07','2023-11-02 11:13:07'),(17,'approval_affiliation_amount_withdrawal_request',1,'affiliate_course','[\"affiliator\"]','{\"affiliator\":\"1\"}','{\"affiliator\":\"0\"}','{\"affiliator\":\"Congartulation ! Your withdrawal request has been approved\"}','{\"affiliator\":\"Congartulation ! Your payment request has been approved.\"}','Approval of withdrawal request of affiliation','Send mail, when you approved the affiliation withdrawal request','1684303480','2023-11-02 11:13:07','2023-11-02 11:13:07'),(18,'course_gift',1,NULL,'[\"payer\",\"receiver\"]','{\"payer\":\"1\",\"receiver\":\"1\"}','{\"payer\":\"1\",\"receiver\":\"1\"}','{\"payer\":\"You have gift a course\",\"receiver\":\"You have received a course gift\"}','{\"payer\":\"You have gift a course to [user_name] [course_title][instructor]\",\"receiver\":\"You have received a course gift by [payer][course_title][instructor]\"}','Course gift notification','Notify users after course gift','1691818623','2023-11-02 11:13:07','2023-11-06 05:02:28');

