INSERT INTO `personalized_courses` VALUES (2,5,1,15,NULL,'Mastering English Grammar: From Beginner to Confident','mastering-english-grammar-from-beginner-to-confident-5-00952','This course targets common grammar pitfalls for beginner learners, focusing on sentence structure, subject-verb agreement, punctuation, and parallel structure. Through clear explanations and targeted practice, you will build a solid foundation to avoid frequent errors and improve your writing accuracy.','[\"correct\",\"sentence\",\"select\",\"error\",\"correctly\",\"word\",\"choose\",\"client\"]','en','beginner','ready','ai','2026-05-14 05:35:52','2026-05-14 05:35:52'),(3,5,1,17,NULL,'Mastering Grammar: From Errors to Excellence','mastering-grammar-from-errors-to-excellence-5-01613','This course targets common grammar pitfalls for intermediate learners, focusing on punctuation, subject-verb agreement, and word choice. Through targeted lessons and practice, you\'ll build confidence in using semicolons, apostrophes, and correct verb forms.','[\"correct\",\"select\",\"error\",\"sentence\",\"correctly\",\"account\",\"manager\",\"available\"]','en','intermediate','ready','ai','2026-05-14 05:46:53','2026-05-14 05:46:53');

