INSERT INTO `questions` VALUES (1,1,'Which sentence is grammatically correct?','mcq','[\"The team has completed its report ahead of schedule.\"]','[\"The team have completed their report ahead of schedule.\",\"The team has completed its report ahead of schedule.\",\"The team has completed their reports ahead of schedule.\",\"The team have completed its report ahead of schedules.\"]',1,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(2,1,'Choose the correct word to complete the sentence: \"The client requested that the interpreter ____ present for all sessions.\"','mcq','[\"be\"]','[\"is\",\"be\",\"was\",\"will be\"]',2,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(3,1,'Which sentence uses the semicolon correctly?','mcq','[\"The report was thorough; however, it lacked specific data on interpreter response times.\"]','[\"The report was thorough; however, it lacked specific data on interpreter response times.\",\"The report was thorough; and it lacked specific data on interpreter response times.\",\"The report was thorough, however; it lacked specific data on interpreter response times.\",\"The report; was thorough however it lacked specific data on interpreter response times.\"]',3,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(4,1,'Identify the sentence with a dangling modifier:','mcq','[\"After reviewing the contract, several concerns were raised.\"]','[\"After reviewing the contract, the legal team approved the terms.\",\"After reviewing the contract, several concerns were raised.\",\"The legal team, after reviewing the contract, approved the terms.\",\"The contract was approved after the legal team reviewed it.\"]',4,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(5,1,'Which is correct? \"Neither the account manager ____ the SDR ____ available for the meeting.\"','mcq','[\"nor \\/ is\"]','[\"or \\/ are\",\"nor \\/ is\",\"or \\/ is\",\"nor \\/ are\"]',5,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(6,1,'Select the correctly punctuated sentence:','mcq','[\"The client who signed last week wants to add three more languages.\"]','[\"The client who signed last week, wants to add three more languages.\",\"The client, who signed last week wants to add three more languages.\",\"The client who signed last week wants to add three more languages.\",\"The client who signed last week wants, to add three more languages.\"]',6,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(7,1,'Which word correctly completes this sentence? \"The discrepancy between the two reports ____ significant.\"','mcq','[\"is\"]','[\"are\",\"were\",\"is\",\"have been\"]',7,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(8,1,'Choose the correct form: \"Each of the interpreters ____ required to submit a weekly availability form.\"','mcq','[\"is\"]','[\"are\",\"is\",\"were\",\"have been\"]',8,'2026-04-07 22:12:04','2026-04-07 22:12:04'),(9,1,'Which sentence avoids the passive voice most effectively?','mcq','[\"A scheduling error caused the SLA breach.\"]','[\"The SLA breach was caused by a scheduling error.\",\"A scheduling error caused the SLA breach.\",\"The SLA breach had been caused by a scheduling error.\",\"It was a scheduling error that had caused the SLA breach.\"]',9,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(10,1,'Identify the sentence with correct parallel structure:','mcq','[\"The training covers writing emails, managing CRM entries, and practicing phone etiquette.\"]','[\"The training covers writing emails, how to manage CRM entries, and phone etiquette.\",\"The training covers writing emails, managing CRM entries, and practicing phone etiquette.\",\"The training covers how to write emails, CRM management, and phone etiquette practice.\",\"The training covers email writing, to manage CRM entries, and phone etiquette.\"]',10,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(11,1,'Which is correct? \"The data ____ that client satisfaction has improved.\"','mcq','[\"shows\"]','[\"shows\",\"show\",\"are showing\",\"have shown\"]',11,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(12,1,'Select the sentence with correct apostrophe usage:','mcq','[\"The company\'s policy requires two reference checks.\"]','[\"The companys\' policy requires two reference checks.\",\"The company\'s policy requires two reference check\'s.\",\"The company\'s policy requires two reference checks.\",\"The companies policy require\'s two reference checks.\"]',12,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(13,1,'Which sentence is most concise without losing meaning?','mcq','[\"If the interpreter is unavailable, we will find a replacement.\"]','[\"In the event that the interpreter is not available, we will need to find a replacement.\",\"If the interpreter is unavailable, we will find a replacement.\",\"Should it happen that the interpreter is not available at the time, we will need to find a replacement for the interpreter.\",\"In the case that interpreter availability is not possible, replacement finding will be necessary.\"]',13,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(14,1,'Choose the correct word: \"The effect of the new QA process was ____ than expected.\"','mcq','[\"greater\"]','[\"more greater\",\"greater\",\"more great\",\"most great\"]',14,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(15,1,'Which sentence correctly uses \"its\" vs. \"it\'s\"?','mcq','[\"It\'s important that the team meets its deadlines.\"]','[\"Its important that the team meets it\'s deadlines.\",\"It\'s important that the team meets its deadlines.\",\"Its important that the team meets its deadlines.\",\"It\'s important that the team meets it\'s deadlines.\"]',15,'2026-04-07 22:12:05','2026-04-07 22:12:05'),(16,1,'Error 1: Select the correct replacement for \"you\'re\" in \"Thank you for you\'re continued partnership.\"','mcq','[\"your\"]','[\"you\'re\",\"your\",\"yours\",\"you are\"]',16,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(17,1,'Error 2: Select the correct replacement for \"writting\".','mcq','[\"writing\"]','[\"writting\",\"writtingg\",\"writing\",\"writen\"]',17,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(18,1,'Error 3: Select the correct replacement for \"maintainance\".','mcq','[\"maintenance\"]','[\"maintainance\",\"maintenance\",\"maintenence\",\"maintnance\"]',18,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(19,1,'Error 4: Select the correct correction for \"maybe\" in this context.','mcq','[\"may be\"]','[\"maybe\",\"may bee\",\"may be\",\"maybeen\"]',19,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(20,1,'Error 5: Select the correct replacement for \"unavailble\".','mcq','[\"unavailable\"]','[\"unavailble\",\"unavailable\",\"unavailabel\",\"unavaiable\"]',20,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(21,1,'Error 6: Select the correct replacement for \"availible\".','mcq','[\"available\"]','[\"availible\",\"available\",\"avalable\",\"availlable\"]',21,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(22,1,'Error 7: Select the correct verb in \"Each of our interpreters ____ prepared\".','mcq','[\"is\"]','[\"are\",\"were\",\"is\",\"have\"]',22,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(23,1,'Error 8: Select the correct replacement for \"maintanence\".','mcq','[\"maintenance\"]','[\"maintanence\",\"maintenance\",\"maintainance\",\"maintnance\"]',23,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(24,1,'Error 9: Select the correct replacement for \"inconveniance\".','mcq','[\"inconvenience\"]','[\"inconveniance\",\"inconvenients\",\"inconvenience\",\"inconvience\"]',24,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(25,1,'Error 10: Select the correct word in \"... account manager, whom is available ...\".','mcq','[\"who\"]','[\"whom\",\"whose\",\"who\",\"which\"]',25,'2026-04-07 22:55:45','2026-04-07 22:55:45'),(26,1,'PART C: Professional Writing Prompt (40 points)','long_answer',NULL,'[\"Instructions: Write a professional email (150\\u2013250 words). Scenario: You work at Defrilex. A healthcare client reported an interpreter arrived 10 minutes late yesterday, causing the patient appointment to run over. The client is frustrated. Acknowledge the issue, explain the cause (technical connectivity issue), list prevention steps (backup interpreter protocol and pre-session connectivity checks), and reaffirm Defrilex commitment to service quality.\"]',26,'2026-04-07 23:11:20','2026-04-07 23:11:20'),(27,2,'Prompt 1 (Structured Introduction, 2 minutes): Please introduce yourself in about two minutes. Tell me your name, your professional background, what you are looking for in your next role, and why Defrilex interests you. Organize your response with a clear beginning, middle, and end.','speaking_prompt',NULL,'{\"video_url\":\"\\/video\\/test1.mp4\"}',1,'2026-04-08 00:29:09','2026-04-08 05:44:55'),(28,2,'Prompt 2 (Scenario Response, 3 minutes): Imagine you are a Defrilex team member. A client calls and says: \"We had an interpreter session yesterday and the interpreter seemed unprepared. They did not know the medical terminology relevant to our specialty. This is unacceptable.\" How would you respond to this client right now on the phone? Speak as if you are actually on that call.','speaking_prompt',NULL,'{\"video_url\":\"\\/video\\/test1.mp4\"}',2,'2026-04-08 00:29:09','2026-04-08 05:44:55'),(29,2,'Prompt 3 (Impromptu Explanation, 3 minutes): Explain to a potential client who knows nothing about the industry why a healthcare company should use a professional language services provider instead of relying on bilingual staff members. Organize your explanation clearly.','speaking_prompt',NULL,'{\"video_url\":\"\\/video\\/test1.mp4\"}',3,'2026-04-08 00:29:09','2026-04-08 05:44:55'),(30,3,'What is the keyboard shortcut to copy selected text on most systems?','mcq','[\"Ctrl + C\"]','[\"Ctrl + V\",\"Ctrl + C\",\"Ctrl + X\",\"Ctrl + Z\"]',1,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(31,3,'You need to send a large file (50 MB) to a client. What is the most professional approach?','mcq','[\"Upload it to a cloud storage platform and share the link.\"]','[\"Attach it directly to the email.\",\"Upload it to a cloud storage platform and share the link.\",\"Compress it into multiple ZIP files and send several emails.\",\"Print it and mail a physical copy.\"]',2,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(32,3,'Which file format is best for sending a finalized document that should not be easily edited by the recipient?','mcq','[\".pdf\"]','[\".docx\",\".xlsx\",\".pdf\",\".txt\"]',3,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(33,3,'You are on a video call and your audio is not working. What is the best first troubleshooting step?','mcq','[\"Check that the correct microphone is selected in the video call settings.\"]','[\"Restart your computer immediately.\",\"Check that the correct microphone is selected in the video call settings.\",\"Send a message saying your computer is broken.\",\"Leave the call and email the other participants instead.\"]',4,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(34,3,'What does BCC mean in an email, and when should you use it?','mcq','[\"Blind Carbon Copy \\u2014 use it to send a copy to someone without other recipients seeing their address.\"]','[\"Blind Carbon Copy \\u2014 use it to send a copy to someone without other recipients seeing their address.\",\"Basic Carbon Copy \\u2014 use it for all group emails.\",\"Backup Carbon Copy \\u2014 use it to save a copy of the email.\",\"Block Carbon Copy \\u2014 use it to prevent replies.\"]',5,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(35,3,'In Google Sheets or Excel, which formula would you use to add up all values in cells A1 through A10?','mcq','[\"=SUM(A1:A10)\"]','[\"=ADD(A1:A10)\",\"=SUM(A1:A10)\",\"=TOTAL(A1:A10)\",\"=COUNT(A1:A10)\"]',6,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(36,3,'What is the purpose of a VPN in a remote work environment?','mcq','[\"To create a secure, encrypted connection to protect data.\"]','[\"To make your internet faster.\",\"To create a secure, encrypted connection to protect data.\",\"To block websites you should not visit.\",\"To replace your WiFi router.\"]',7,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(37,3,'A colleague shares a Google Doc with you and asks for feedback. Where should you add your comments?','mcq','[\"Use the comment feature (Ctrl+Alt+M or Insert > Comment).\"]','[\"Edit the text directly without telling them.\",\"Use the comment feature (Ctrl+Alt+M or Insert > Comment).\",\"Copy the document and email your version back.\",\"Print it and write notes in pen.\"]',8,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(38,3,'You accidentally delete an important file from your desktop. What should you do first?','mcq','[\"Check the Recycle Bin or Trash folder.\"]','[\"Accept the loss and recreate it from memory.\",\"Check the Recycle Bin or Trash folder.\",\"Call IT support immediately.\",\"Restart your computer.\"]',9,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(39,3,'Which of these is NOT a cloud storage platform?','mcq','[\"Microsoft Notepad\"]','[\"Google Drive\",\"Dropbox\",\"Microsoft Notepad\",\"OneDrive\"]',10,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(40,3,'You receive an email with the subject line: \'URGENT: Your account has been compromised. Click here to verify.\' What should you do?','mcq','[\"Do not click the link. Report it to your IT team or manager as a potential phishing attempt.\"]','[\"Click the link immediately to protect your account.\",\"Forward it to your entire team as a warning.\",\"Do not click the link. Report it to your IT team or manager as a potential phishing attempt.\",\"Reply asking them to verify their identity.\"]',11,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(41,3,'What does Ctrl + Z do?','mcq','[\"Undo the last action\"]','[\"Zoom in\",\"Close the application\",\"Undo the last action\",\"Save the file\"]',12,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(42,3,'You need to join a Zoom meeting but the link says \'Meeting has not started.\' The meeting was supposed to start 2 minutes ago. What do you do?','mcq','[\"Wait a reasonable time (3-5 minutes), check your calendar for the correct link, and message the host if the issue persists.\"]','[\"Give up and email the host that you tried.\",\"Wait a reasonable time (3-5 minutes), check your calendar for the correct link, and message the host if the issue persists.\",\"Join a random Zoom room and hope it is the right one.\",\"Restart your computer.\"]',13,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(43,3,'What file extension indicates a spreadsheet file?','mcq','[\".xlsx\"]','[\".pptx\",\".xlsx\",\".docx\",\".pdf\"]',14,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(44,3,'Which of the following best describes what \'the cloud\' means in computing?','mcq','[\"Remote servers accessed via the internet that store and process data.\"]','[\"A physical server in your office.\",\"Remote servers accessed via the internet that store and process data.\",\"A special type of WiFi network.\",\"Software that only works offline.\"]',15,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(45,3,'Scenario: Your manager asks you to create a shared folder where the whole team can upload documents and everyone can view them. What is the best approach?','mcq','[\"Create a shared folder on Google Drive or SharePoint with appropriate access permissions.\"]','[\"Create a folder on your local desktop and email each file individually.\",\"Create a shared folder on Google Drive or SharePoint with appropriate access permissions.\",\"Create a ZIP file and email it to everyone.\",\"Post files one by one in a group chat.\"]',16,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(46,3,'What does the \'Reply All\' button do in email?','mcq','[\"Sends your reply to the sender and all other recipients on the email.\"]','[\"Sends your reply only to the original sender.\",\"Sends your reply to the sender and all other recipients on the email.\",\"Forwards the email to your entire company.\",\"Deletes the email and creates a new one.\"]',17,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(47,3,'You are working on a document and your computer suddenly shuts down. What feature would have helped prevent data loss?','mcq','[\"Auto-save \\/ cloud sync\"]','[\"Larger monitor\",\"Auto-save \\/ cloud sync\",\"Faster internet\",\"More RAM\"]',18,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(48,3,'Which keyboard shortcut selects all text in a document?','mcq','[\"Ctrl + A\"]','[\"Ctrl + S\",\"Ctrl + P\",\"Ctrl + A\",\"Ctrl + F\"]',19,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(49,3,'A client sends you a .csv file. What type of data does this file typically contain?','mcq','[\"Tabular data (rows and columns) that can be opened in a spreadsheet application.\"]','[\"A presentation with slides.\",\"A video recording.\",\"Tabular data (rows and columns) that can be opened in a spreadsheet application.\",\"An image file.\"]',20,'2026-04-16 07:15:55','2026-04-16 07:15:55'),(50,4,'What is the most accurate description of what a large language model (like Claude or ChatGPT) does?','mcq','[\"It generates text by predicting the most likely next words based on patterns learned from training data.\"]','[\"It understands human language the same way humans do.\",\"It generates text by predicting the most likely next words based on patterns learned from training data.\",\"It searches the internet in real time to find answers.\",\"It stores a database of all correct answers to all questions.\"]',1,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(51,4,'You use an AI tool to draft a client proposal. What should you do before sending it?','mcq','[\"Review every claim, verify any data or statistics, edit for tone, and ensure it reflects Defrilex standards.\"]','[\"Send it immediately - AI output is always professional and accurate.\",\"Review every claim, verify any data or statistics, edit for tone, and ensure it reflects Defrilex standards.\",\"Add your name to it and send it without reading.\",\"Ask the AI to verify its own work.\"]',2,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(52,4,'What is \'AI hallucination\'?','mcq','[\"When the AI generates information that sounds plausible but is factually incorrect.\"]','[\"When the AI tool crashes.\",\"When the AI generates information that sounds plausible but is factually incorrect.\",\"When the AI runs too slowly.\",\"When the AI tool asks too many questions.\"]',3,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(53,4,'Which of the following is the BEST use of AI in a professional setting?','mcq','[\"Using AI to draft a first version of an email that you then review and edit.\"]','[\"Using AI to make the final hiring decision on a candidate.\",\"Using AI to draft a first version of an email that you then review and edit.\",\"Using AI to generate your weekly performance numbers.\",\"Using AI to sign contracts on your behalf.\"]',4,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(54,4,'When writing a prompt for an AI tool, which approach will produce the best results?','mcq','[\"Be specific about context, audience, tone, length, and desired output.\"]','[\"Keep it as short as possible: \'Write email.\'\",\"Be specific about context, audience, tone, length, and desired output.\",\"Write in all capitals so the AI pays more attention.\",\"Copy and paste your entire inbox and say \'Handle this.\'\"]',5,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(55,4,'Which of the following should you NEVER put into a public AI tool without proper data agreements?','mcq','[\"Client personal health information, social security numbers, or confidential financial data.\"]','[\"A request to summarize a public news article.\",\"Client personal health information, social security numbers, or confidential financial data.\",\"A request to explain a grammar rule.\",\"A request to brainstorm marketing ideas.\"]',6,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(56,4,'AI is best at which type of task?','mcq','[\"Drafting, summarizing, analyzing patterns, and generating first versions of content.\"]','[\"Making ethical judgments about people.\",\"Drafting, summarizing, analyzing patterns, and generating first versions of content.\",\"Replacing the need for any human review.\",\"Guaranteeing 100% accuracy on all factual claims.\"]',7,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(57,4,'An AI tool gives you a statistic: \'Healthcare interpretation errors cause 47% of malpractice claims.\' What should you do?','mcq','[\"Verify the statistic independently before using it in any professional document.\"]','[\"Include it in your report - the AI found it so it must be real.\",\"Verify the statistic independently before using it in any professional document.\",\"Ignore it - AI statistics are always wrong.\",\"Ask the AI where it got the number and accept whatever source it provides.\"]',8,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(58,4,'What is the most important limitation to remember when using AI tools for work?','mcq','[\"They can generate confident-sounding but incorrect information and they do not truly understand context the way humans do.\"]','[\"They are too expensive to use regularly.\",\"They can generate confident-sounding but incorrect information and they do not truly understand context the way humans do.\",\"They only work in English.\",\"They cannot generate text longer than one paragraph.\"]',9,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(59,4,'Defrilex uses AI to assist with CRM data entry, proposal drafting, and meeting summaries. Who is ultimately responsible for the accuracy of these outputs?','mcq','[\"The person who uses the AI output in their work.\"]','[\"The AI tool provider.\",\"The person who uses the AI output in their work.\",\"The IT department.\",\"No one - AI is responsible for its own outputs.\"]',10,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(60,4,'Scenario: You are preparing a compliance document for a healthcare client. You use AI to draft the document. The AI produces a detailed draft that references specific HIPAA regulations by number. You are not sure if the regulation numbers are correct. What is the best course of action?','mcq','[\"Verify every regulation number against official HIPAA documentation before submitting.\"]','[\"Submit the draft as-is since the AI seems confident.\",\"Verify every regulation number against official HIPAA documentation before submitting.\",\"Delete the regulation numbers and submit without references.\",\"Ask a colleague who also does not know HIPAA to review it.\"]',11,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(61,4,'Scenario: Your manager asks you to use AI to summarize 50 pages of client feedback notes. The AI summary misses a critical complaint that appeared in the notes. What does this situation teach you about AI?','mcq','[\"AI summaries are helpful starting points but must be reviewed against the source material, especially for critical details.\"]','[\"AI summaries are useless and should never be used.\",\"AI summaries are helpful starting points but must be reviewed against the source material, especially for critical details.\",\"The AI must be broken and should be reported to IT.\",\"You should use a different AI tool that never makes mistakes.\"]',12,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(62,4,'Scenario: A colleague says: \'I just paste all my client emails into ChatGPT and have it write all my replies. I do not even read the responses before sending.\' How would you evaluate this practice?','mcq','[\"This is risky and unprofessional. AI responses need human review for accuracy, tone, and appropriateness before being sent to clients.\"]','[\"This is efficient and should be encouraged across the team.\",\"This is risky and unprofessional. AI responses need human review for accuracy, tone, and appropriateness before being sent to clients.\",\"This is fine as long as the client does not know.\",\"This is acceptable for internal emails but not external ones.\"]',13,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(63,4,'Describe one specific way you could use an AI tool to improve your productivity in a work setting. Be specific about the task, the tool, and how you would ensure the output meets professional standards.','long_answer','[]',NULL,14,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(64,4,'In your own words, explain why it is important for humans to review AI-generated content before using it in professional communications. Give one example of what could go wrong if they do not.','long_answer','[]',NULL,15,'2026-04-16 07:19:48','2026-04-16 07:19:48'),(65,5,'You receive an email from \'IT-Support@defr1lex.com\' asking you to click a link and verify your password. What should you do?','mcq','[\"Do not click the link. The sender domain is suspicious (defr1lex instead of defrilex). Report it to your manager or IT.\"]','[\"Click the link and enter your password - IT needs it.\",\"Do not click the link. The sender domain is suspicious (defr1lex instead of defrilex). Report it to your manager or IT.\",\"Forward it to the whole team so they can verify too.\",\"Reply asking if it is legitimate.\"]',1,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(66,5,'Which of the following is the strongest password?','mcq','[\"j7$Kp!mN2@xQ9vLz\"]','[\"password123\",\"Defrilex2026!\",\"j7$Kp!mN2@xQ9vLz\",\"MyDogFido\"]',2,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(67,5,'You are working from a coffee shop. Which of the following is the safest practice?','mcq','[\"Use your phone\'s hotspot or a VPN to create a secure connection.\"]','[\"Use the public WiFi and access all your work tools normally.\",\"Use your phone\'s hotspot or a VPN to create a secure connection.\",\"Ask the barista for the WiFi password and share it with your team.\",\"Turn off your firewall so the public WiFi works better.\"]',3,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(68,5,'A colleague messages you on Slack: \'Hey, can you send me the client database password? I lost mine.\' What should you do?','mcq','[\"Tell them to reset their password through the official IT process. Never share credentials via chat.\"]','[\"Send the password - they are a colleague.\",\"Tell them to reset their password through the official IT process. Never share credentials via chat.\",\"Send it but tell them to delete the message afterward.\",\"Look up the password and call them to share it verbally.\"]',4,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(69,5,'What is \'two-factor authentication\' (2FA)?','mcq','[\"A security method that requires two forms of verification (e.g., password + phone code) to access an account.\"]','[\"Using two different passwords for the same account.\",\"A security method that requires two forms of verification (e.g., password + phone code) to access an account.\",\"Logging in from two different devices at the same time.\",\"A backup password in case you forget your main one.\"]',5,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(70,5,'You find a USB drive in the parking lot with a label that says \'Employee Salaries Q2.\' What should you do?','mcq','[\"Turn it in to your manager or IT without plugging it in - it could contain malware.\"]','[\"Plug it into your computer to see what is on it.\",\"Turn it in to your manager or IT without plugging it in - it could contain malware.\",\"Plug it in to find out who it belongs to so you can return it.\",\"Keep it - finder\'s keepers.\"]',6,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(71,5,'Which of the following is an example of social engineering?','mcq','[\"Someone calling and pretending to be IT support to trick you into revealing your login credentials.\"]','[\"A hacker exploiting a software vulnerability.\",\"Someone calling and pretending to be IT support to trick you into revealing your login credentials.\",\"A computer virus spreading through email attachments.\",\"A firewall blocking suspicious traffic.\"]',7,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(72,5,'Your work laptop is stolen from your car. What should you do FIRST?','mcq','[\"Report the theft immediately to your manager and IT so the device can be remotely wiped and accounts can be secured.\"]','[\"Buy a new laptop.\",\"Report the theft immediately to your manager and IT so the device can be remotely wiped and accounts can be secured.\",\"Wait a few days to see if it turns up.\",\"Post about it on social media.\"]',8,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(73,5,'How often should you update your work passwords?','mcq','[\"Per your company\'s policy (typically every 60-90 days) or immediately if you suspect compromise.\"]','[\"Never - a good password lasts forever.\",\"Per your company\'s policy (typically every 60-90 days) or immediately if you suspect compromise.\",\"Only when IT forces you to.\",\"Once a year is sufficient.\"]',9,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(74,5,'A client sends you sensitive patient information via regular unencrypted email. What should you do?','mcq','[\"Acknowledge receipt, then inform your manager that unencrypted transmission of sensitive data is a compliance risk and work to establish a secure transfer method.\"]','[\"Save it to your desktop and use it normally.\",\"Acknowledge receipt, then inform your manager that unencrypted transmission of sensitive data is a compliance risk and work to establish a secure transfer method.\",\"Forward it to your personal email as a backup.\",\"Reply and ask them to send more details.\"]',10,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(75,5,'Scenario: You receive a phone call from someone claiming to be from your company IT department. They say there has been a data breach and they need your login credentials immediately to secure your account. What should you do?','mcq','[\"Hang up and contact IT through official channels (email, Slack, or known phone number) to verify the request.\"]','[\"Provide your credentials - it is an emergency.\",\"Hang up and contact IT through official channels (email, Slack, or known phone number) to verify the request.\",\"Give them only your username but not your password.\",\"Ask them to email you instead.\"]',11,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(76,5,'Scenario: You notice that a coworker is using the same simple password for every tool and has it written on a sticky note on their monitor. What is the appropriate response?','mcq','[\"Privately and respectfully tell them this is a security risk and suggest they use a password manager.\"]','[\"Mind your own business.\",\"Privately and respectfully tell them this is a security risk and suggest they use a password manager.\",\"Report them to HR immediately.\",\"Take a photo of the sticky note for evidence.\"]',12,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(77,5,'Scenario: A client asks you to email them a spreadsheet containing patient names and appointment details. Your company policy requires encrypted file transfer for this type of data. What should you do?','mcq','[\"Explain to the client that this data must be transferred via the secure method required by company policy, and offer to send it through the approved encrypted channel.\"]','[\"Send it via regular email since the client asked for it.\",\"Explain to the client that this data must be transferred via the secure method required by company policy, and offer to send it through the approved encrypted channel.\",\"Send it via email but password-protect the file.\",\"Refuse to send it at all.\"]',13,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(78,5,'Scenario: You accidentally click on a suspicious link in an email. The page looked strange but you closed it immediately. What should you do?','mcq','[\"Report the incident to IT immediately, do not enter any credentials on any site until cleared, and note the email details.\"]','[\"Nothing - you closed it so you are fine.\",\"Report the incident to IT immediately, do not enter any credentials on any site until cleared, and note the email details.\",\"Run your own antivirus scan and consider it resolved.\",\"Delete the email and pretend it did not happen.\"]',14,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(79,5,'Scenario: You are asked to share your screen during a video call with a client. You have other client confidential information open in another tab. What should you do before sharing your screen?','mcq','[\"Close all tabs and windows containing confidential information for other clients before sharing, or share only the specific application window needed.\"]','[\"Share your screen immediately - the client probably will not notice.\",\"Close all tabs and windows containing confidential information for other clients before sharing, or share only the specific application window needed.\",\"Ask the client to look away while you close things.\",\"It does not matter - all your clients are in the same industry anyway.\"]',15,'2026-04-16 08:09:54','2026-04-16 08:09:54'),(80,6,'Scenario: You wake up feeling slightly unwell but could still work at reduced capacity. Your team has a deadline today. What should you do?','mcq','[\"Notify your manager immediately, communicate your reduced capacity, and ask how to prioritize your tasks given the deadline.\"]','[\"Work without telling anyone - push through.\",\"Notify your manager immediately, communicate your reduced capacity, and ask how to prioritize your tasks given the deadline.\",\"Call in sick and do not check in until tomorrow.\",\"Work but only on easy tasks and hope no one notices the deadline items are late.\"]',1,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(81,6,'Scenario: You are working from home and realize you have been stuck on a problem for over an hour with no progress. What is the best approach?','mcq','[\"Message your manager or a colleague, explain the problem clearly, what you have tried, and ask for guidance.\"]','[\"Keep trying for the rest of the day - you will figure it out eventually.\",\"Message your manager or a colleague, explain the problem clearly, what you have tried, and ask for guidance.\",\"Switch to a different task and hope the problem resolves itself.\",\"Wait until the next scheduled meeting to bring it up.\"]',2,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(82,6,'Scenario: Your internet connection drops during an important client call. What should you do?','mcq','[\"Immediately switch to your phone hotspot or backup connection, message the meeting organizer via chat to explain the disruption, and rejoin as quickly as possible.\"]','[\"Wait and hope it reconnects.\",\"Immediately switch to your phone hotspot or backup connection, message the meeting organizer via chat to explain the disruption, and rejoin as quickly as possible.\",\"Send an email apologizing after the call is over.\",\"Cancel the rest of your day since your internet is unreliable.\"]',3,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(83,6,'Scenario: You finished your assigned tasks for the day by 2 PM. There is no specific work queued for the afternoon. What should you do?','mcq','[\"Proactively message your manager about your availability, offer to take on additional tasks, or use the time for skill development or process improvement.\"]','[\"Log off early - you finished your work.\",\"Proactively message your manager about your availability, offer to take on additional tasks, or use the time for skill development or process improvement.\",\"Watch videos until end of day.\",\"Do personal errands and stay logged in.\"]',4,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(84,6,'Scenario: A colleague sends you a Slack message at 8 PM asking for something non-urgent. What is the appropriate response?','mcq','[\"Acknowledge it the next morning during your work hours, unless it is flagged as urgent.\"]','[\"Respond immediately regardless of the hour.\",\"Acknowledge it the next morning during your work hours, unless it is flagged as urgent.\",\"Ignore it entirely.\",\"Tell them they should not message after hours.\"]',5,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(85,6,'Scenario: You have a scheduled video meeting but your home environment is noisy (construction outside, family members present). What should you do?','mcq','[\"Find the quietest space available, use a headset, mute when not speaking, and briefly apologize for any background noise if necessary.\"]','[\"Join with your camera and microphone on and hope for the best.\",\"Find the quietest space available, use a headset, mute when not speaking, and briefly apologize for any background noise if necessary.\",\"Skip the meeting and ask for notes afterward.\",\"Join audio-only and do not explain.\"]',6,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(86,6,'Scenario: Your manager sends you a task on Monday morning with a Friday deadline. By Wednesday, you realize you will not finish by Friday. What should you do?','mcq','[\"Notify your manager on Wednesday (not Friday) that you are at risk of missing the deadline, explain why, and propose solutions (deadline extension, reduced scope, or help).\"]','[\"Push through and deliver whatever you have on Friday without mentioning the issue.\",\"Notify your manager on Wednesday (not Friday) that you are at risk of missing the deadline, explain why, and propose solutions (deadline extension, reduced scope, or help).\",\"Wait until Thursday to mention it.\",\"Quietly reduce the quality to meet the deadline.\"]',7,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(87,6,'Scenario: You are asked to submit a daily end-of-day report. You had a day with mostly meetings and no significant output. What should you write?','mcq','[\"Honestly document the day: meetings attended, key takeaways, decisions made, and what you plan to accomplish tomorrow. Flag that the meeting load impacted output time.\"]','[\"\\\"Nothing to report.\\\"\",\"Honestly document the day: meetings attended, key takeaways, decisions made, and what you plan to accomplish tomorrow. Flag that the meeting load impacted output time.\",\"Make up tasks to look productive.\",\"Skip the report for that day.\"]',8,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(88,6,'Scenario: A team member in a different time zone needs your input to proceed with their work. They have been waiting for your response for 6 hours. What does this situation teach you about remote work?','mcq','[\"Asynchronous communication requires proactive responsiveness. When someone is blocked on your input, treating it as high priority reduces total team delay.\"]','[\"Time zones are their problem, not yours.\",\"Asynchronous communication requires proactive responsiveness. When someone is blocked on your input, treating it as high priority reduces total team delay.\",\"They should have called you instead of waiting.\",\"This is why remote work does not really work.\"]',9,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(89,6,'Scenario: You are onboarding at Defrilex. After your first week, you have questions about your role but your manager seems very busy. What should you do?','mcq','[\"Compile your questions in writing, schedule a brief check-in, and come prepared with specific questions to use the manager\'s time efficiently.\"]','[\"Wait for your manager to reach out to you.\",\"Compile your questions in writing, schedule a brief check-in, and come prepared with specific questions to use the manager\'s time efficiently.\",\"Ask random colleagues instead.\",\"Assume you will figure it out on your own over time.\"]',10,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(90,6,'Scenario: Your workspace at home has poor lighting and an unmade bed visible behind you on video calls. Before starting a client-facing role at Defrilex, what should you do?','mcq','[\"Set up a clean, professional background (physical or virtual), ensure good lighting on your face, and test your video setup before your first call.\"]','[\"Do not worry about it - clients understand remote work.\",\"Set up a clean, professional background (physical or virtual), ensure good lighting on your face, and test your video setup before your first call.\",\"Use blur background and never turn your camera on.\",\"Only take audio calls.\"]',11,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(91,6,'Scenario: You completed a task and sent it to your manager, but received no acknowledgment after 24 hours. What should you do?','mcq','[\"Send a polite follow-up message confirming they received the deliverable and asking if they need anything else.\"]','[\"Assume they received it and move on.\",\"Send a polite follow-up message confirming they received the deliverable and asking if they need anything else.\",\"Get offended and stop working.\",\"Resend the same message five times.\"]',12,'2026-04-16 08:11:39','2026-04-16 08:11:39'),(92,7,'Scenario: You made a mistake in a client report that was already sent. Your manager has not noticed yet. What do you do?','mcq','[\"Immediately tell your manager, explain the error, propose how to fix it, and contact the client with a corrected version.\"]','[\"Hope no one notices and fix it quietly if asked.\",\"Immediately tell your manager, explain the error, propose how to fix it, and contact the client with a corrected version.\",\"Blame the data source and say the report was based on bad input.\",\"Wait to see if the client notices before doing anything.\"]',1,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(93,7,'Scenario: A colleague is struggling with their workload and asks you to cover a task that is not your responsibility. You are also busy. What do you do?','mcq','[\"Assess whether you can realistically help without missing your own deadlines. If yes, help. If no, explain honestly and suggest they escalate to the manager.\"]','[\"Say no immediately - it is not your job.\",\"Assess whether you can realistically help without missing your own deadlines. If yes, help. If no, explain honestly and suggest they escalate to the manager.\",\"Say yes and then quietly not do it.\",\"Help them but complain about it to other colleagues.\"]',2,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(94,7,'Scenario: During a team meeting, your manager publicly credits you for work that a colleague actually did most of. What do you do?','mcq','[\"Speak up during or after the meeting and give credit to the colleague who did the majority of the work.\"]','[\"Accept the credit - you were involved.\",\"Speak up during or after the meeting and give credit to the colleague who did the majority of the work.\",\"Say nothing but feel guilty.\",\"Tell the colleague privately that you will give them credit next time.\"]',3,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(95,7,'Scenario: A client asks you to do something that technically violates a company process but would make the client happy. What is the right approach?','mcq','[\"Explain to the client that you want to help them but need to do it within the proper process. Offer an alternative that meets their need while staying within guidelines. Escalate if needed.\"]','[\"Do what the client wants - client satisfaction is the priority.\",\"Explain to the client that you want to help them but need to do it within the proper process. Offer an alternative that meets their need while staying within guidelines. Escalate if needed.\",\"Ignore the request and hope they forget.\",\"Do it but do not tell your manager.\"]',4,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(96,7,'Scenario: You overhear a colleague exaggerating Defrilex\'s capabilities to a potential client during a call. What do you do?','mcq','[\"After the call, privately speak with the colleague and explain that misrepresenting capabilities creates trust risk and potential delivery problems. If the behavior continues, escalate to your manager.\"]','[\"It is not your call - stay out of it.\",\"After the call, privately speak with the colleague and explain that misrepresenting capabilities creates trust risk and potential delivery problems. If the behavior continues, escalate to your manager.\",\"Join the call and contradict them in front of the client.\",\"Tell other colleagues about it but take no action.\"]',5,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(97,7,'Scenario: You are behind on your weekly targets. Your manager asks for your status report. What do you do?','mcq','[\"Report the actual numbers honestly, explain the gap, what caused it, and what you are doing to get back on track.\"]','[\"Inflate the numbers slightly to look better.\",\"Report the actual numbers honestly, explain the gap, what caused it, and what you are doing to get back on track.\",\"Avoid the conversation and submit the report late.\",\"Blame external factors beyond your control.\"]',6,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(98,7,'Scenario: You receive feedback from your manager that your work quality on a recent project was below expectations. How do you respond?','mcq','[\"Listen carefully, ask for specific examples so you understand the gap, acknowledge the feedback, and create a plan to improve.\"]','[\"Defend your work and explain why the feedback is unfair.\",\"Listen carefully, ask for specific examples so you understand the gap, acknowledge the feedback, and create a plan to improve.\",\"Agree outwardly but internally dismiss the feedback.\",\"Get upset and consider looking for another job.\"]',7,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(99,7,'Scenario: You discover that a team process is inefficient and is wasting 3 hours per week of your time. What do you do?','mcq','[\"Document the inefficiency, propose a specific improvement with expected time savings, and present it to your manager.\"]','[\"Follow the process without complaint - it is not your place to change things.\",\"Document the inefficiency, propose a specific improvement with expected time savings, and present it to your manager.\",\"Stop following the process and do it your own way.\",\"Complain about it to colleagues in chat.\"]',8,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(100,7,'Scenario: A critical deadline is approaching and you realize you cannot meet it alone. Asking for help might make you look weak. What do you do?','mcq','[\"Proactively ask for help early, clearly explaining what you need and why. Meeting the team\'s deadline is more important than looking like you can handle everything alone.\"]','[\"Work until 3 AM and deliver something substandard.\",\"Proactively ask for help early, clearly explaining what you need and why. Meeting the team\'s deadline is more important than looking like you can handle everything alone.\",\"Miss the deadline and explain afterward.\",\"Deliver on time but cut quality significantly.\"]',9,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(101,7,'Scenario: A client complains about something that was genuinely not Defrilex\'s fault. How do you handle it?','mcq','[\"Listen empathetically, acknowledge the client\'s frustration, investigate the root cause, and work to resolve the situation regardless of fault attribution. Protecting the relationship matters more than being right.\"]','[\"Tell the client directly that it is not your fault.\",\"Listen empathetically, acknowledge the client\'s frustration, investigate the root cause, and work to resolve the situation regardless of fault attribution. Protecting the relationship matters more than being right.\",\"Ignore the complaint.\",\"Escalate it immediately without attempting resolution.\"]',10,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(102,7,'Scenario: You are given a task you have never done before and do not fully understand. What do you do?','mcq','[\"Ask clarifying questions upfront, research what you do not know, attempt the task, and check in with your manager before finalizing to ensure you are on the right track.\"]','[\"Pretend you understand and figure it out as you go.\",\"Ask clarifying questions upfront, research what you do not know, attempt the task, and check in with your manager before finalizing to ensure you are on the right track.\",\"Wait for someone to explain it step by step before starting.\",\"Delegate it to someone else.\"]',11,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(103,7,'Scenario: A new team member seems to be struggling and appears hesitant to ask for help. What do you do?','mcq','[\"Reach out privately and offer support. Share resources or context that might help them. Let them know it is safe to ask questions.\"]','[\"That is their manager\'s problem.\",\"Reach out privately and offer support. Share resources or context that might help them. Let them know it is safe to ask questions.\",\"Mention their struggles to the team in a meeting.\",\"Do nothing - they will figure it out.\"]',12,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(104,7,'Describe a time in your professional life when you made a significant mistake. What happened, what did you do about it, and what did you learn?','long_answer','[]',NULL,13,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(105,7,'What does \'accountability\' mean to you in a professional context? Give a specific example of what accountability looks like in daily work.','long_answer','[]',NULL,14,'2026-04-16 08:13:31','2026-04-16 08:13:31'),(106,8,'<h5>Exercise 1: Data Error Detection (15 points)</h5>\n<p>Review the following interpreter scheduling data table. <strong>Find and list all errors</strong> (there are 5 errors). Each correctly identified error is worth 3 points. Number your answers clearly.</p>\n<table class=\"table table-bordered table-sm\" style=\"font-size:14px;\">\n<thead><tr><th>Interpreter</th><th>Language</th><th>Date</th><th>Time</th><th>Client</th><th>Status</th></tr></thead>\n<tbody>\n<tr><td>Maria Santos</td><td>Spanish</td><td>03/15/2026</td><td>9:00 AM</td><td>HealthFirst Clinic</td><td>Confirmed</td></tr>\n<tr><td>Jean-Pierre Duval</td><td>Frnech</td><td>03/15/2026</td><td>10:30 AM</td><td>Metro Hospital</td><td>Confirmed</td></tr>\n<tr><td>Yuki Tanaka</td><td>Japanese</td><td>03/16/2026</td><td>2:00 PM</td><td>City Gov\'t Office</td><td>Pending</td></tr>\n<tr><td>Maria Santos</td><td>Spanish</td><td>03/15/2026</td><td>9:30 AM</td><td>Sunrise Medical</td><td>Confirmed</td></tr>\n<tr><td>Ahmed Hassan</td><td>Arabic</td><td>13/17/2026</td><td>11:00 AM</td><td>Legal Aid Society</td><td>Confirmed</td></tr>\n<tr><td>Li Wei</td><td>Mandarin</td><td>03/17/2026</td><td>3:00 PM</td><td>FinTrust Bank</td><td>Confrimed</td></tr>\n<tr><td>Jean-Pierre Duval</td><td>French</td><td>03/18/2026</td><td>9:00 AM</td><td>Metro Hospital</td><td>Pending</td></tr>\n</tbody>\n</table>','long_answer','[]',NULL,1,'2026-04-16 08:21:10','2026-04-16 08:21:10'),(107,8,'<h5>Exercise 2: Email Proofreading (10 points)</h5>\n<p>Read the following internal email. <strong>Identify 5 problems</strong> (factual inconsistencies, tone issues, or errors). Each correctly identified problem is worth 2 points.</p>\n<div style=\"border:1px solid #e2e8f0;padding:16px;border-radius:8px;background:#f8fafc;\">\n<p><strong>Subject:</strong> Quarterly Results — Great Quarter!</p>\n<p>Team,</p>\n<p>I wanted to share that Q1 results are in. We closed 12 new clients this quarter, which is below our target of 15. Our revenue grew by 18% compared to last quarter. This was an outstanding quarter all around and everyone should be proud.</p>\n<p>Client retention was 91%, down from 94% last quarter. Also, the new interpreter onboarding process reduced average time-todeploy from 14 days to 9 days, which is a huge win for the Operations team lead by Marcus.</p>\n<p>Looking forward to an even better Q2!</p>\n<p>Best,<br>Fritz</p>\n</div>','long_answer','[]',NULL,2,'2026-04-16 08:21:10','2026-04-16 08:21:10'),(108,8,'<h5>Exercise 3: Process Checklist Validation (15 points)</h5>\n<p>Below is a checklist for onboarding a new healthcare client at Defrilex. <strong>Review it and identify 5 missing or out-of-order steps</strong> that would create risk. Each correctly identified issue is worth 3 points.</p>\n<ol style=\"line-height:1.8;\">\n<li>Receive signed contract from sales team.</li>\n<li>Assign account manager.</li>\n<li>Begin interpreter scheduling for first sessions.</li>\n<li>Conduct client kickoff call.</li>\n<li>Set up client in billing system.</li>\n<li>Send welcome packet to client.</li>\n<li>Launch service delivery.</li>\n<li>Conduct 30-day review with client.</li>\n</ol>','long_answer','[]',NULL,3,'2026-04-16 08:21:10','2026-04-16 08:21:10'),(109,8,'<h5>Exercise 4: Number Verification (10 points)</h5>\n<p>The following summary paragraph describes performance metrics. <strong>Verify whether the paragraph\'s claims are consistent with the data provided below it.</strong> Identify any discrepancies (there are 5). Each correctly identified discrepancy is worth 2 points.</p>\n<div style=\"border:1px solid #e2e8f0;padding:16px;border-radius:8px;margin-bottom:12px;\">\n<p><strong>Summary:</strong> \"In March 2026, Defrilex completed 847 interpretation sessions across 12 language pairs. The average QA score was 94.2%, up from 91.8% in February. Client satisfaction reached 4.7 out of 5.0. Response time averaged 3.2 minutes, meeting our SLA of under 5 minutes. Spanish was our highest-volume language at 312 sessions.\"</p>\n</div>\n<p><strong>Actual Data:</strong></p>\n<ul>\n<li>Total sessions: 874.</li>\n<li>Language pairs served: 14.</li>\n<li>Average QA score: 92.4% (February: 91.8%).</li>\n<li>Client satisfaction: 4.7/5.0.</li>\n<li>Average response time: 3.2 minutes.</li>\n<li>SLA target: under 5 minutes.</li>\n<li>Spanish sessions: 312.</li>\n<li>Haitian Creole sessions: 318.</li>\n</ul>','long_answer','[]',NULL,4,'2026-04-16 08:21:10','2026-04-16 08:21:10'),(110,9,'<h5>Exercise 1: Passage Transcription (3 minutes)</h5>\n<p>Type the following passage as accurately as possible within 3 minutes.</p>\n<blockquote style=\"background:#f8fafc;border-left:4px solid #cbd5e1;padding:12px 14px;\">\n\"Defrilex provides multilingual services to organizations in healthcare, government, financial services, and technology. Our interpreters and agents are professionally vetted, QA-scored, and deployed through both managed service engagements and our talent marketplace platform. Every session is monitored for quality. Every client relationship is managed by a dedicated account team. Our commitment to compliance, accuracy, and cultural competency differentiates us from commodity language service providers. We believe that language access is not a convenience but a fundamental requirement for equitable service delivery in regulated industries.\"\n</blockquote>\n<p><strong>Evaluator:</strong> score WPM and accuracy for this exercise.</p>','long_answer','[]',NULL,1,'2026-04-17 07:02:29','2026-04-17 07:02:29'),(111,9,'<h5>Exercise 2: Dictation Typing (2 minutes)</h5>\n<p>The evaluator reads the following text aloud at moderate pace. Candidate types what they hear within 2 minutes.</p>\n<blockquote style=\"background:#f8fafc;border-left:4px solid #cbd5e1;padding:12px 14px;\">\n\"The client onboarding process at Defrilex follows a structured timeline. Within the first three business days, the account manager conducts a kickoff call, confirms language requirements, and establishes quality benchmarks. By day seven, the first interpreter sessions are scheduled and the client has access to the reporting dashboard.\"\n</blockquote>\n<p><strong>Evaluator:</strong> score WPM and accuracy for dictation performance.</p>','long_answer','[]',NULL,2,'2026-04-17 07:02:29','2026-04-17 07:02:29'),(112,10,'Scenario: During a medical interpretation session, the patient tells you (the interpreter) privately that they are not taking their prescribed medication but asks you not to tell the doctor. What should you do?','mcq','[\"Explain to the patient that as an interpreter, you are required to interpret everything said during the session. Encourage the patient to share this with the doctor, but make clear that you cannot withhold medically relevant information.\"]','[\"Keep the patient\'s secret - they trusted you.\",\"Explain to the patient that as an interpreter, you are required to interpret everything said during the session. Encourage the patient to share this with the doctor, but make clear that you cannot withhold medically relevant information.\",\"Tell the doctor immediately without informing the patient.\",\"Ignore it - it is not your medical concern.\"]',1,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(113,10,'Scenario: A doctor uses a highly technical medical term you do not know. What is the correct course of action?','mcq','[\"Pause the conversation, inform both parties that you need clarification on the term, ask the doctor to explain or use simpler language, and then interpret accurately.\"]','[\"Guess the meaning based on context and interpret your best guess.\",\"Pause the conversation, inform both parties that you need clarification on the term, ask the doctor to explain or use simpler language, and then interpret accurately.\",\"Skip the term and continue interpreting.\",\"Make up a similar-sounding word in the target language.\"]',2,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(114,10,'Scenario: The patient becomes emotional and starts crying during a session about a terminal diagnosis. The doctor pauses. What is your role?','mcq','[\"Remain professional and composed. Allow the pause. Do not add personal commentary. When the conversation resumes, interpret accurately and with appropriate emotional tone without inserting your own emotions.\"]','[\"Comfort the patient and offer your personal advice.\",\"Remain professional and composed. Allow the pause. Do not add personal commentary. When the conversation resumes, interpret accurately and with appropriate emotional tone without inserting your own emotions.\",\"Tell the patient to calm down so the session can continue.\",\"Start a side conversation with the patient in their language.\"]',3,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(115,10,'Scenario: A client\'s family member in the room starts interpreting for the patient instead of allowing you to interpret. What should you do?','mcq','[\"Politely but firmly explain that for accuracy and compliance purposes, you are the designated professional interpreter and all communication should go through you. Address this to the provider so they can reinforce the protocol.\"]','[\"Let them interpret - they know the patient better.\",\"Politely but firmly explain that for accuracy and compliance purposes, you are the designated professional interpreter and all communication should go through you. Address this to the provider so they can reinforce the protocol.\",\"Argue with the family member.\",\"Leave the session.\"]',4,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(116,10,'Scenario: You are interpreting a legal proceeding and the attorney asks you to explain a legal concept to the client, not just interpret. What should you do?','mcq','[\"Clarify your role: you are there to interpret, not to provide legal advice or explanations. Suggest the attorney explain the concept in simpler terms, which you will then interpret.\"]','[\"Explain the concept since you understand it.\",\"Clarify your role: you are there to interpret, not to provide legal advice or explanations. Suggest the attorney explain the concept in simpler terms, which you will then interpret.\",\"Refuse and say nothing.\",\"Give a brief explanation but note it is not legal advice.\"]',5,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(117,10,'Scenario: You are assigned to interpret for a patient who speaks a dialect of your language that you do not fully understand. What is the appropriate action?','mcq','[\"Inform the scheduler or supervisor immediately that you may not be fully proficient in this dialect. Request a more qualified interpreter or confirm with the patient that communication is clear before proceeding.\"]','[\"Proceed and do your best.\",\"Inform the scheduler or supervisor immediately that you may not be fully proficient in this dialect. Request a more qualified interpreter or confirm with the patient that communication is clear before proceeding.\",\"Cancel the session without explanation.\",\"Use a translation app to help.\"]',6,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(118,10,'Scenario: After a session, the client (healthcare provider) asks you for your personal opinion about whether the patient seemed honest. How should you respond?','mcq','[\"Explain that providing personal assessments of patients is outside your role as an interpreter. Your job is to convey what was said accurately, not to evaluate the speakers.\"]','[\"Share your honest opinion - you are trying to help.\",\"Explain that providing personal assessments of patients is outside your role as an interpreter. Your job is to convey what was said accurately, not to evaluate the speakers.\",\"Give a vague, non-committal answer.\",\"Report the provider for asking inappropriate questions.\"]',7,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(119,10,'Scenario: You recognize the patient in an interpretation session as someone from your personal community. What should you do?','mcq','[\"Disclose the potential conflict of interest to the scheduler. If the patient is comfortable proceeding and confidentiality can be maintained, continue with extra care. If either party is uncomfortable, request reassignment.\"]','[\"Proceed normally - you can be professional.\",\"Disclose the potential conflict of interest to the scheduler. If the patient is comfortable proceeding and confidentiality can be maintained, continue with extra care. If either party is uncomfortable, request reassignment.\",\"Refuse the session immediately.\",\"Chat with them personally before the session starts.\"]',8,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(120,10,'Scenario: The provider is speaking very quickly and you are falling behind in interpretation. What is the correct action?','mcq','[\"Politely interrupt and ask the provider to slow down or pause periodically so you can provide complete and accurate interpretation.\"]','[\"Summarize instead of interpreting word-for-word to keep up.\",\"Politely interrupt and ask the provider to slow down or pause periodically so you can provide complete and accurate interpretation.\",\"Just interpret the parts you caught.\",\"Stop interpreting and wait for them to finish.\"]',9,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(121,10,'Scenario: During a government benefits interview, the client says something in their language that you believe may be inaccurate based on what you know about their situation. What should you do?','mcq','[\"Interpret exactly what the client said, without modification, addition, or omission. It is not your role to evaluate the accuracy of what speakers say - only to convey it faithfully.\"]','[\"Correct the client\'s statement to be accurate.\",\"Interpret exactly what the client said, without modification, addition, or omission. It is not your role to evaluate the accuracy of what speakers say - only to convey it faithfully.\",\"Add a note that you think the client may be mistaken.\",\"Refuse to interpret a statement you believe is false.\"]',10,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(122,10,'<h5>Practical Exercise: Terminology Preparation (10 points)</h5>\n<p>You are assigned to interpret a <strong>cardiology</strong> appointment tomorrow. The patient speaks <strong>[your target language]</strong>.</p>\n<p><strong>List 10 medical terms</strong> you would prepare in advance for this session, and for <strong>each</strong>, explain briefly why an interpreter would need to know this term for a cardiology appointment.</p>','long_answer','[]',NULL,11,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(123,10,'<h5>Role-Play Preparation: Session Introduction (10 points)</h5>\n<p>Write out the <strong>exact introduction script</strong> you would deliver at the beginning of an <strong>OPI (over-the-phone interpretation)</strong> session for a healthcare appointment.</p>\n<p>Include: your introduction, role clarification, confidentiality statement, and instructions for the provider and patient.</p>','long_answer','[]',NULL,12,'2026-04-17 07:36:24','2026-04-17 07:36:24'),(124,11,'Scenario: You are prospecting for Defrilex. You find a healthcare system with 15 hospitals. They currently use a competitor for interpretation services. Their contract renews in 8 months. What is the best next step?','mcq','[\"Research their specific pain points, identify the decision-maker, and begin a long-cycle relationship-building outreach strategy. An 8-month runway is ideal for trust-building before renewal.\"]','[\"Send a cold email with Defrilex pricing to undercut the competitor.\",\"Research their specific pain points, identify the decision-maker, and begin a long-cycle relationship-building outreach strategy. An 8-month runway is ideal for trust-building before renewal.\",\"Wait until 2 months before renewal to reach out.\",\"Call the front desk and ask to speak to whoever handles language services.\"]',1,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(125,11,'Scenario: During a discovery call, the prospect says: \'We are not really looking to switch providers right now. We just took the meeting out of curiosity.\' How do you handle this?','mcq','[\"Acknowledge their honesty and reframe: \'That is perfectly fine. My goal is not to sell you today but to understand your current setup so that if you ever do evaluate options, you already know what is possible. Can I ask a few questions about how things are working now?\'\"]','[\"End the call - they are not interested.\",\"Acknowledge their honesty and reframe: \'That is perfectly fine. My goal is not to sell you today but to understand your current setup so that if you ever do evaluate options, you already know what is possible. Can I ask a few questions about how things are working now?\'\",\"Push harder to create urgency.\",\"Offer a discount to get them interested.\"]',2,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(126,11,'Scenario: A prospect seems very interested and wants to move fast, but they are a small company with only 5 employees, no regulated-industry clients, and a very small budget. What should you do?','mcq','[\"Qualify honestly: this prospect does not fit Defrilex\'s ICP. Politely explain that Defrilex may not be the best fit for their current needs. Recommend an alternative if appropriate. Do not waste pipeline space on bad-fit deals.\"]','[\"Close the deal quickly - revenue is revenue.\",\"Qualify honestly: this prospect does not fit Defrilex\'s ICP. Politely explain that Defrilex may not be the best fit for their current needs. Recommend an alternative if appropriate. Do not waste pipeline space on bad-fit deals.\",\"Offer a massive discount to make it work.\",\"Add them to the pipeline at a high stage to make your numbers look good.\"]',3,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(127,11,'Scenario: The prospect says: \'Your competitor offers the same services at 20% less.\' What is the best response?','mcq','[\"I understand price is a factor. Can I ask what matters most to you beyond price? In regulated industries, the cost of a quality failure often exceeds the savings on a lower-priced provider. Let me show you specifically how our QA process, compliance posture, and interpreter vetting protect your organization.\"]','[\"We can match that price.\",\"I understand price is a factor. Can I ask what matters most to you beyond price? In regulated industries, the cost of a quality failure often exceeds the savings on a lower-priced provider. Let me show you specifically how our QA process, compliance posture, and interpreter vetting protect your organization.\",\"You get what you pay for.\",\"Let me check with my manager about a discount.\"]',4,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(128,11,'Scenario: You have a discovery call with a government agency. They are asking detailed questions about compliance certifications you are not sure Defrilex currently holds. What do you do?','mcq','[\"Be honest: \'That is an important question. I want to give you an accurate answer, so let me confirm the specific certifications we hold and get back to you by tomorrow. I do not want to misrepresent anything.\'\"]','[\"Imply that Defrilex has all the certifications - you can figure it out later.\",\"Be honest: \'That is an important question. I want to give you an accurate answer, so let me confirm the specific certifications we hold and get back to you by tomorrow. I do not want to misrepresent anything.\'\",\"Change the subject to avoid the question.\",\"Make up certification names that sound plausible.\"]',5,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(129,11,'Scenario: You closed a deal and the sales-to-operations handoff is happening. Operations has concerns about the timeline you promised the client. What is the appropriate action?','mcq','[\"Listen to the operations concerns. If the timeline is not feasible, proactively manage the client\'s expectations before there is a delivery failure. Never sell what ops cannot fulfill.\"]','[\"Tell ops to figure it out - the deal is closed.\",\"Listen to the operations concerns. If the timeline is not feasible, proactively manage the client\'s expectations before there is a delivery failure. Never sell what ops cannot fulfill.\",\"Ignore the concerns and hope it works out.\",\"Blame ops for being slow.\"]',6,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(130,11,'Scenario: Your pipeline is below target this quarter. You have a prospect who might close but has not returned your last two emails. What do you do?','mcq','[\"Evaluate: have you provided genuine value in your outreach? Try a different channel (LinkedIn, phone). Provide a specific insight or resource relevant to their business. If they remain unresponsive after a reasonable sequence, move on and focus on healthier pipeline.\"]','[\"Send five more emails this week.\",\"Evaluate: have you provided genuine value in your outreach? Try a different channel (LinkedIn, phone). Provide a specific insight or resource relevant to their business. If they remain unresponsive after a reasonable sequence, move on and focus on healthier pipeline.\",\"Mark them as closing this month in the CRM to improve your forecast numbers.\",\"Give up on them entirely.\"]',7,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(131,11,'Scenario: A prospect asks you to send a proposal before you have completed a discovery call. How do you respond?','mcq','[\"I would love to send you something relevant. To make sure the proposal actually addresses your specific situation, can we schedule a 30-minute call so I can tailor it to your needs? A generic proposal would not do your evaluation justice.\"]','[\"Send a generic proposal immediately.\",\"I would love to send you something relevant. To make sure the proposal actually addresses your specific situation, can we schedule a 30-minute call so I can tailor it to your needs? A generic proposal would not do your evaluation justice.\",\"Refuse to send anything without a full sales cycle.\",\"Send the proposal and hope it works.\"]',8,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(132,11,'<h5>Practical Exercise 1: Discovery Call Outline (15 points)</h5>\n<p><strong>Scenario:</strong> You are preparing for a 30-minute discovery call with the VP of Patient Services at a mid-size hospital system. They currently use ad-hoc bilingual staff for most interpretation needs but have had compliance concerns.</p>\n<p><strong>Write a discovery call outline</strong> that includes:</p>\n<ul>\n<li>Your opening (how you set the agenda)</li>\n<li>5 specific discovery questions you would ask (explain what each reveals)</li>\n<li>How you would close the call (next steps)</li>\n</ul>','long_answer','[]',NULL,9,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(133,11,'<h5>Practical Exercise 2: Prospecting Prioritization (15 points)</h5>\n<p>You have 5 prospects in your pipeline. <strong>Rank them from highest to lowest priority</strong> and explain your reasoning for each ranking. Use what you know about Defrilex\'s ICP (regulated industries, trust-first buyers, compliance needs).</p>\n<p><strong>Prospect A:</strong> Large regional hospital system (200 beds). Current interpretation provider contract expires in 6 months. VP of Patient Experience responded to your LinkedIn message.</p>\n<p><strong>Prospect B:</strong> Small marketing agency. 10 employees. Needs occasional translation for ad copy. Found you on Google.</p>\n<p><strong>Prospect C:</strong> State government agency responsible for Medicaid enrollment. No current language services provider. Issued an RFI last month.</p>\n<p><strong>Prospect D:</strong> Large fintech company. 500 employees. Growing international customer base. No language service provider yet. Your cold email got no response.</p>\n<p><strong>Prospect E:</strong> Mid-size law firm specializing in immigration. Currently uses freelance interpreters found on Craigslist. Partner expressed frustration with quality.</p>','long_answer','[]',NULL,10,'2026-04-18 05:39:55','2026-04-18 05:39:55'),(134,12,'Scenario: Defrilex\'s website currently says: \'We provide the best language services at the lowest prices!\' What is wrong with this messaging for a company targeting regulated-industry buyers?','mcq','[\"It emphasizes price over trust and quality, which is the opposite of what regulated-industry buyers care about. It sounds generic and does not address compliance, quality, or risk reduction.\"]','[\"Nothing - it is clear and compelling.\",\"It emphasizes price over trust and quality, which is the opposite of what regulated-industry buyers care about. It sounds generic and does not address compliance, quality, or risk reduction.\",\"It should say lowest prices guaranteed.\",\"It needs more exclamation points.\"]',1,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(135,12,'Scenario: A healthcare compliance officer is evaluating Defrilex\'s website. What content would be MOST important for them to find? Choose the most critical content:','mcq','[\"Compliance certifications, HIPAA awareness, QA methodology, interpreter vetting process, and SLA commitments.\"]','[\"Customer testimonials from small businesses.\",\"Compliance certifications, HIPAA awareness, QA methodology, interpreter vetting process, and SLA commitments.\",\"A flashy video about the company culture.\",\"Pricing tables.\"]',2,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(136,12,'Scenario: You are writing a case study about a healthcare client engagement. The client had a 15% improvement in patient satisfaction scores after using Defrilex. What is the most effective way to present this?','mcq','[\"Frame the full story: the challenge (language barriers causing patient dissatisfaction and compliance risk), the solution (Defrilex managed interpretation service with QA scoring), and the specific, measurable result with context for why it matters to similar buyers.\"]','[\"Just state the number: Patient satisfaction improved 15%.\",\"Frame the full story: the challenge (language barriers causing patient dissatisfaction and compliance risk), the solution (Defrilex managed interpretation service with QA scoring), and the specific, measurable result with context for why it matters to similar buyers.\",\"Exaggerate it to 25% to be more impressive.\",\"Do not use numbers - they are boring.\"]',3,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(137,12,'Which marketing channel is typically MOST effective for reaching regulated-industry enterprise buyers?','mcq','[\"Targeted LinkedIn outreach, industry conference presence, and thought leadership content that addresses their specific compliance and operational challenges.\"]','[\"TikTok ads.\",\"Targeted LinkedIn outreach, industry conference presence, and thought leadership content that addresses their specific compliance and operational challenges.\",\"Mass email blasts to purchased lists.\",\"Facebook ads targeting healthcare workers.\"]',4,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(138,12,'Scenario: Sales asks you to create a one-pager that makes Defrilex look like a large, established company even though it is early-stage. How should you handle this?','mcq','[\"Create a one-pager that is credible and compelling without misrepresenting company size. Focus on quality of service, team expertise, compliance posture, and specific results. Regulated buyers value substance over size.\"]','[\"Create the one-pager as requested - sales knows what clients want.\",\"Create a one-pager that is credible and compelling without misrepresenting company size. Focus on quality of service, team expertise, compliance posture, and specific results. Regulated buyers value substance over size.\",\"Refuse - marketing should not support sales.\",\"Include fake client logos to look bigger.\"]',5,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(139,12,'Scenario: You notice that Defrilex social media posts are getting engagement from individual language learners but not from enterprise procurement people. What does this tell you and what should you do?','mcq','[\"The content strategy is attracting the wrong audience. Shift content toward enterprise topics: compliance challenges, SLA frameworks, cost-of-poor-quality analysis, case studies. Target content to where decision-makers are, not where general interest is.\"]','[\"Engagement is engagement - keep doing what works.\",\"The content strategy is attracting the wrong audience. Shift content toward enterprise topics: compliance challenges, SLA frameworks, cost-of-poor-quality analysis, case studies. Target content to where decision-makers are, not where general interest is.\",\"Post more frequently to get more of the same engagement.\",\"Stop using social media entirely.\"]',6,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(140,12,'<h5>Practical Exercise 1: Messaging Rewrite (15 points)</h5>\n<p>Rewrite the following <strong>homepage headline and subheadline</strong> for Defrilex, targeting a <strong>VP of Patient Services</strong> at a hospital system. Your messaging must <strong>reduce perceived buyer risk</strong> and emphasize <strong>trust, quality, and compliance</strong>.</p>\n<p><strong>Current:</strong> \"Fast, Affordable Language Services for Everyone! Get started in minutes!\"</p>\n<p>Provide your rewritten headline and subheadline below.</p>','long_answer','[]',NULL,7,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(141,12,'<h5>Practical Exercise 2: Content Brief (15 points)</h5>\n<p>Write a <strong>content brief</strong> for a blog post titled: <strong>\"Why Bilingual Staff Are Not a Substitute for Professional Medical Interpreters.\"</strong></p>\n<p>Include:</p>\n<ul>\n<li>Target audience</li>\n<li>Key message</li>\n<li>5 main points to cover</li>\n<li>Desired CTA</li>\n<li>SEO keywords</li>\n</ul>','long_answer','[]',NULL,8,'2026-04-18 05:42:04','2026-04-18 05:42:04'),(142,13,'Scenario: You are managing interpreter scheduling. A healthcare client needs a Haitian Creole interpreter for a session in 45 minutes. Your primary interpreter just called in unavailable. What do you do?','mcq','[\"Immediately activate the backup interpreter protocol: check the secondary and tertiary interpreter lists, confirm availability, brief the backup on the client\'s needs, and communicate the status to the client within 15 minutes.\"]','[\"Tell the client you cannot fulfill the request.\",\"Immediately activate the backup interpreter protocol: check the secondary and tertiary interpreter lists, confirm availability, brief the backup on the client\'s needs, and communicate the status to the client within 15 minutes.\",\"Wait to see if the primary interpreter changes their mind.\",\"Ask the client to reschedule.\"]',1,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(143,13,'Scenario: Your SLA with a client specifies 95% on-time interpreter connection. This month, you are at 91% with one week remaining. What do you do?','mcq','[\"Analyze which sessions missed the SLA and why. Implement specific fixes for the root causes this week. Proactively communicate the current status to the account manager so they can manage the client relationship. Create a corrective action plan.\"]','[\"Hope the last week brings the average up.\",\"Analyze which sessions missed the SLA and why. Implement specific fixes for the root causes this week. Proactively communicate the current status to the account manager so they can manage the client relationship. Create a corrective action plan.\",\"Lower the SLA target.\",\"Wait until the monthly report to address it.\"]',2,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(144,13,'Scenario: Sales closes a new client and promises a 5-day deployment timeline. Operations typically needs 10 days for proper setup. How should operations handle this?','mcq','[\"Raise the concern immediately. Work with sales and the client to establish a realistic timeline. Propose a phased launch: begin with core services in 5 days, full deployment in 10. Never sacrifice setup quality for unrealistic timelines.\"]','[\"Just do it in 5 days by cutting corners.\",\"Raise the concern immediately. Work with sales and the client to establish a realistic timeline. Propose a phased launch: begin with core services in 5 days, full deployment in 10. Never sacrifice setup quality for unrealistic timelines.\",\"Refuse the timeline and tell sales they made a mistake.\",\"Start the setup but do not tell anyone it will be late until it is late.\"]',3,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(145,13,'Scenario: A client reports that interpreter quality has declined over the past month. QA scores do not show a decline. What should you investigate?','mcq','[\"Investigate deeper: review the specific interpreters assigned to this client, check if QA scoring criteria still align with client expectations, ask the client for specific examples, and consider whether QA rubric needs updating for this client\'s specialty. Client perception IS a quality signal even when QA scores look fine.\"]','[\"Tell the client the QA data does not support their claim.\",\"Investigate deeper: review the specific interpreters assigned to this client, check if QA scoring criteria still align with client expectations, ask the client for specific examples, and consider whether QA rubric needs updating for this client\'s specialty. Client perception IS a quality signal even when QA scores look fine.\",\"Ignore it - the data says quality is fine.\",\"Replace all interpreters assigned to this client.\"]',4,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(146,13,'Scenario: Two clients have conflicting urgent needs at the same time and you only have one available interpreter who can serve both. How do you prioritize?','mcq','[\"Evaluate based on: contractual SLA priority, patient\\/case urgency, relationship impact, and whether alternative coverage exists for either client. Make a decision, document it, and communicate transparently with the deprioritized client about when they will receive coverage.\"]','[\"First come, first served.\",\"Evaluate based on: contractual SLA priority, patient\\/case urgency, relationship impact, and whether alternative coverage exists for either client. Make a decision, document it, and communicate transparently with the deprioritized client about when they will receive coverage.\",\"Flip a coin.\",\"Tell both clients there is a system outage.\"]',5,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(147,13,'Scenario: You notice that the same scheduling error has occurred three times this month, each time with a different coordinator. What is the appropriate response?','mcq','[\"Treat it as a process problem, not a people problem. Investigate the root cause: is the scheduling tool confusing? Is a process step unclear? Fix the system\\/process to prevent the error, then retrain the team on the corrected process.\"]','[\"Discipline the coordinators.\",\"Treat it as a process problem, not a people problem. Investigate the root cause: is the scheduling tool confusing? Is a process step unclear? Fix the system\\/process to prevent the error, then retrain the team on the corrected process.\",\"Ignore it - three times is not a pattern.\",\"Add more review steps to slow the process down.\"]',6,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(148,13,'Scenario: A new operations team member is ramping up and asks you to check all their work before it goes out. How do you handle this?','mcq','[\"Check their work closely for the first 2-4 weeks, provide specific feedback on errors, then gradually reduce oversight as they demonstrate accuracy. The goal is independence, not dependence.\"]','[\"Check everything for them indefinitely.\",\"Check their work closely for the first 2-4 weeks, provide specific feedback on errors, then gradually reduce oversight as they demonstrate accuracy. The goal is independence, not dependence.\",\"Tell them to figure it out on their own.\",\"Have them watch you do it instead of doing it themselves.\"]',7,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(149,13,'Scenario: At the end of the month, you discover that a billing error resulted in a client being undercharged by $2,400. What do you do?','mcq','[\"Document the error, determine root cause, fix the billing process to prevent recurrence, and work with the account manager to communicate transparently with the client and arrange correction. Honesty protects long-term trust.\"]','[\"Absorb the loss - it is your team\'s mistake.\",\"Document the error, determine root cause, fix the billing process to prevent recurrence, and work with the account manager to communicate transparently with the client and arrange correction. Honesty protects long-term trust.\",\"Bill the client silently next month and hope they do not notice.\",\"Wait until the client notices and then fix it.\"]',8,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(150,13,'<h5>Practical Exercise: Incident Response Documentation (20 points)</h5>\n<p><strong>Scenario:</strong> A government client\\\'s scheduled interpretation session (Spanish, legal proceeding) did not connect. The interpreter was logged in but the client\\\'s platform had a configuration error. The session was delayed by 25 minutes. The client\\\'s SLA specifies a maximum 5-minute connection time.</p>\n<p>Write a <strong>complete incident report</strong> covering:</p>\n<ul>\n<li>What happened (facts only)</li>\n<li>Root cause analysis</li>\n<li>Immediate resolution steps taken</li>\n<li>Client communication plan</li>\n<li>Preventive measures for the future</li>\n<li>Who owns each follow-up action</li>\n</ul>\n<p>Keep it concise and professional.</p>','long_answer','[]',NULL,9,'2026-04-18 06:14:41','2026-04-18 06:14:41'),(151,14,'Scenario: A team member has missed their targets for two consecutive months. They are well-liked by the team and have a positive attitude. What is the right management approach?','mcq','[\"Have a direct, documented conversation about the performance gap. Use specific data. Ask what is causing the miss. Agree on a clear improvement plan with weekly check-ins and a defined timeline. Attitude does not substitute for results.\"]','[\"Give them more time - they have a great attitude.\",\"Have a direct, documented conversation about the performance gap. Use specific data. Ask what is causing the miss. Agree on a clear improvement plan with weekly check-ins and a defined timeline. Attitude does not substitute for results.\",\"Quietly move their targets lower so they can hit them.\",\"Wait for the quarterly review to address it.\"]',1,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(152,14,'Scenario: Two of your direct reports have a personal conflict that is affecting team dynamics. How do you handle it?','mcq','[\"Address it directly. Meet with each person separately to understand perspectives, then facilitate a conversation focused on professional behavior expectations and team impact. Make clear that personal conflict cannot affect team performance or client delivery.\"]','[\"Stay out of it - they are adults.\",\"Address it directly. Meet with each person separately to understand perspectives, then facilitate a conversation focused on professional behavior expectations and team impact. Make clear that personal conflict cannot affect team performance or client delivery.\",\"Transfer one of them to another team.\",\"Pretend you do not notice.\"]',2,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(153,14,'Scenario: Your team is overloaded and morale is dropping. Leadership asks you to take on an additional project. What do you do?','mcq','[\"Present leadership with a clear picture of current capacity: active projects, deadlines, team utilization. Ask them to help prioritize: what gets deprioritized or delayed to make room? Protect your team from burnout while being transparent about trade-offs.\"]','[\"Accept it and push the team harder.\",\"Present leadership with a clear picture of current capacity: active projects, deadlines, team utilization. Ask them to help prioritize: what gets deprioritized or delayed to make room? Protect your team from burnout while being transparent about trade-offs.\",\"Reject the project without explaining why.\",\"Accept it but do not tell your team about the additional work.\"]',3,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(154,14,'Scenario: A team member delivers excellent work but consistently does not document their process or update the CRM. How do you handle this?','mcq','[\"Acknowledge the excellent work quality, then address the documentation gap directly: explain why it matters (team continuity, client visibility, process scalability), set a clear expectation with a deadline, and follow up. Excellence includes discipline.\"]','[\"Let it slide - the work quality is what matters.\",\"Acknowledge the excellent work quality, then address the documentation gap directly: explain why it matters (team continuity, client visibility, process scalability), set a clear expectation with a deadline, and follow up. Excellence includes discipline.\",\"Do the documentation yourself.\",\"Assign someone else to document their work.\"]',4,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(155,14,'Scenario: You need to deliver difficult feedback to a high-performing team member about their communication style, which others find dismissive. How do you approach the conversation?','mcq','[\"Schedule a private 1:1. Use specific behavioral examples (SBI model): describe the situation, the specific behavior observed, and its impact on the team. Frame it as development, not criticism. Set clear expectations for change.\"]','[\"Skip it - they are a top performer and you do not want to demotivate them.\",\"Schedule a private 1:1. Use specific behavioral examples (SBI model): describe the situation, the specific behavior observed, and its impact on the team. Frame it as development, not criticism. Set clear expectations for change.\",\"Address it in a team meeting so everyone hears.\",\"Send an anonymous message.\"]',5,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(156,14,'Scenario: A project is failing and it is primarily due to decisions you made as the manager. How do you handle this with your team and with leadership?','mcq','[\"Own the decisions that led to the situation. Be transparent with both your team and leadership about what went wrong and what you are doing to correct course. Model the accountability you expect from your team.\"]','[\"Blame external factors.\",\"Own the decisions that led to the situation. Be transparent with both your team and leadership about what went wrong and what you are doing to correct course. Model the accountability you expect from your team.\",\"Quietly fix it without drawing attention.\",\"Shift responsibility to the team members who executed the plan.\"]',6,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(157,14,'Scenario: You have a team member who has been at Defrilex for 6 months and is clearly in the wrong seat (values fit is strong, capability fit is poor for this role). What is the right approach?','mcq','[\"Have an honest, respectful conversation: acknowledge their values and character, but address the capability gap directly. Explore whether a different seat at Defrilex would be a better fit. Set a 30-day evaluation period for the transition.\"]','[\"Keep them in the role and hope they improve.\",\"Have an honest, respectful conversation: acknowledge their values and character, but address the capability gap directly. Explore whether a different seat at Defrilex would be a better fit. Set a 30-day evaluation period for the transition.\",\"Fire them immediately.\",\"Give them a promotion to a different role.\"]',7,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(158,14,'Scenario: Leadership asks you to implement a new process that you believe will not work. How do you handle the disagreement?','mcq','[\"Raise your concerns directly with leadership: present specific reasons with data or evidence for why you believe the approach has risks. Propose alternatives. If leadership still decides to proceed, commit to implementing it well and tracking results honestly.\"]','[\"Implement it without saying anything.\",\"Raise your concerns directly with leadership: present specific reasons with data or evidence for why you believe the approach has risks. Propose alternatives. If leadership still decides to proceed, commit to implementing it well and tracking results honestly.\",\"Refuse to implement it.\",\"Implement it but tell your team it was not your idea.\"]',8,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(159,14,'Describe a situation where you had to hold someone accountable for underperformance. What specific steps did you take, and what was the outcome?','long_answer','[]',NULL,9,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(160,14,'What is your approach to running effective 1:1 meetings with direct reports? What does a typical 1:1 agenda look like for you?','long_answer','[]',NULL,10,'2026-04-18 06:17:10','2026-04-18 06:17:10'),(161,15,'Defrilex bills a healthcare client $50 per interpretation session. The interpreter is paid $25 per session. What is the gross margin per session?','mcq','[\"50%\"]','[\"25%\",\"50%\",\"75%\",\"100%\"]',1,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(162,15,'A client is billed monthly based on session volume. In March, 120 sessions were delivered but only 115 were logged in the billing system. What risk does this create?','mcq','[\"Revenue leakage. The 5 unbilled sessions represent lost revenue. This indicates a process gap between service delivery tracking and billing that must be investigated and fixed.\"]','[\"No risk - 5 sessions is immaterial.\",\"Revenue leakage. The 5 unbilled sessions represent lost revenue. This indicates a process gap between service delivery tracking and billing that must be investigated and fixed.\",\"Overbilling risk.\",\"Compliance risk only.\"]',2,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(163,15,'Scenario: The CEO asks you to prepare a financial report for a board meeting. You discover that one revenue figure is $40K higher than what the data supports. The CEO wants to present the higher number. What do you do?','mcq','[\"Present the accurate number with full documentation. Explain the discrepancy to the CEO privately and recommend presenting truthful figures. Financial integrity is non-negotiable.\"]','[\"Use the higher number - the CEO requested it.\",\"Present the accurate number with full documentation. Explain the discrepancy to the CEO privately and recommend presenting truthful figures. Financial integrity is non-negotiable.\",\"Use the lower number but do not tell the CEO you changed it.\",\"Average the two numbers.\"]',3,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(164,15,'What is the difference between revenue and cash collected?','mcq','[\"Revenue is recognized when earned (services delivered); cash collected is when payment is actually received. In a services business, the timing difference creates accounts receivable.\"]','[\"They are the same thing.\",\"Revenue is recognized when earned (services delivered); cash collected is when payment is actually received. In a services business, the timing difference creates accounts receivable.\",\"Revenue is always higher than cash collected.\",\"Cash collected is a subset of profit.\"]',4,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(165,15,'Scenario: You notice that DSO (Days Sales Outstanding) has increased from 35 days to 52 days over the past quarter. What does this signal and what action should you take?','mcq','[\"It signals that clients are taking longer to pay. Investigate: are specific clients responsible? Are invoices being sent on time? Are there disputes? Implement targeted collection follow-up and report the trend to leadership as a cash flow risk.\"]','[\"It is normal fluctuation.\",\"It signals that clients are taking longer to pay. Investigate: are specific clients responsible? Are invoices being sent on time? Are there disputes? Implement targeted collection follow-up and report the trend to leadership as a cash flow risk.\",\"It means revenue is declining.\",\"Wait another quarter to see if it resolves.\"]',5,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(166,15,'Defrilex signs a 12-month contract worth $120,000 with a new client. How should this revenue be recognized?','mcq','[\"Recognize $10,000 per month as services are delivered over the 12-month period.\"]','[\"Recognize the full $120,000 when the contract is signed.\",\"Recognize $10,000 per month as services are delivered over the 12-month period.\",\"Recognize it when cash is received.\",\"Recognize half upfront and half at the end.\"]',6,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(167,15,'Scenario: You are reviewing monthly expenses and notice that a software subscription increased from $200/month to $800/month with no approval documentation. What should you do?','mcq','[\"Flag it for investigation. Determine who authorized the change, whether it was needed, and whether proper approval was obtained. Even small unauthorized expenses indicate process gaps that can grow.\"]','[\"It is only $600 - not worth investigating.\",\"Flag it for investigation. Determine who authorized the change, whether it was needed, and whether proper approval was obtained. Even small unauthorized expenses indicate process gaps that can grow.\",\"Cancel the subscription immediately.\",\"Let it go this month and watch for next month.\"]',7,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(168,15,'Scenario: A client disputes an invoice, claiming they were billed for sessions that did not occur. Your delivery records are incomplete for that period. How should this be handled?','mcq','[\"Acknowledge the dispute, investigate by cross-referencing all available records (interpreter logs, platform data, client-side records), and resolve with transparency. If records cannot confirm delivery, credit the client. Then fix the record-keeping gap.\"]','[\"Tell the client the invoice is correct.\",\"Acknowledge the dispute, investigate by cross-referencing all available records (interpreter logs, platform data, client-side records), and resolve with transparency. If records cannot confirm delivery, credit the client. Then fix the record-keeping gap.\",\"Credit the full invoice without investigation.\",\"Ignore the dispute and send a reminder.\"]',8,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(169,15,'<h5>Practical Exercise: Billing Discrepancy Analysis (20 points)</h5>\n<p>Review the following data and <strong>identify all discrepancies</strong>. For each, state the <strong>issue</strong>, the <strong>financial impact</strong>, and your <strong>recommended resolution</strong>.</p>\n<ul style=\"line-height:1.75;\">\n<li><strong>Client:</strong> Metro Hospital System</li>\n<li><strong>Contract Rate:</strong> $55 per OPI session, $75 per VRI session</li>\n<li><strong>March Delivery Report:</strong> 180 OPI sessions, 45 VRI sessions delivered</li>\n<li><strong>March Invoice Sent:</strong> $9,900 for OPI (180 x $55), $3,000 for VRI (45 x $67), Total: $12,900</li>\n<li><strong>March Payment Received:</strong> $12,900</li>\n<li><strong>Interpreter Payroll for This Client:</strong> 180 OPI sessions at $28/session = $5,040. 45 VRI sessions at $38/session = $1,710. Total: $6,750.</li>\n</ul>','long_answer','[]',NULL,9,'2026-04-18 06:18:30','2026-04-18 06:18:30'),(170,16,'PART A — Which encryption standard is most commonly required for protecting health data at rest?','mcq','[\"AES-256\"]','[\"MD5\",\"AES-256\",\"Base64\",\"ROT13\"]',1,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(171,16,'PART A — What is the principle of least privilege?','mcq','[\"Granting users only the minimum access permissions necessary to perform their job functions.\"]','[\"Giving all employees admin access for efficiency.\",\"Granting users only the minimum access permissions necessary to perform their job functions.\",\"Restricting access only for contractors.\",\"Giving maximum access to senior staff.\"]',2,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(172,16,'PART A — Defrilex processes Protected Health Information (PHI) for healthcare clients. Which regulation primarily governs this data?','mcq','[\"HIPAA\"]','[\"GDPR\",\"PCI-DSS\",\"HIPAA\",\"SOX\"]',3,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(173,16,'PART A — What is a Business Associate Agreement (BAA) and why does Defrilex need one?','mcq','[\"A legally required agreement between a covered entity and a business associate (like Defrilex) that handles PHI, defining data protection obligations.\"]','[\"A partnership agreement for revenue sharing.\",\"A legally required agreement between a covered entity and a business associate (like Defrilex) that handles PHI, defining data protection obligations.\",\"An employment contract.\",\"A marketing agreement.\"]',4,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(174,16,'PART A — Which of the following is the MOST effective defense against phishing attacks?','mcq','[\"A combination of employee security awareness training, email filtering, multi-factor authentication, and a culture of reporting suspicious communications.\"]','[\"Antivirus software.\",\"A combination of employee security awareness training, email filtering, multi-factor authentication, and a culture of reporting suspicious communications.\",\"Blocking all external emails.\",\"Stronger passwords.\"]',5,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(175,16,'PART A — What is the purpose of a SOC 2 audit?','mcq','[\"To evaluate an organization\'s information security controls based on trust service criteria (security, availability, processing integrity, confidentiality, privacy).\"]','[\"To audit financial statements.\",\"To evaluate an organization\'s information security controls based on trust service criteria (security, availability, processing integrity, confidentiality, privacy).\",\"To check employee performance.\",\"To audit marketing claims.\"]',6,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(176,16,'PART A — What does MFA stand for and why is it important?','mcq','[\"Multi-Factor Authentication - requires two or more verification methods, significantly reducing the risk of unauthorized access even if passwords are compromised.\"]','[\"Multi-File Archive - important for data compression.\",\"Multi-Factor Authentication - requires two or more verification methods, significantly reducing the risk of unauthorized access even if passwords are compromised.\",\"Master File Access - important for database management.\",\"Multiple Firewall Architecture - important for network security.\"]',7,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(177,16,'PART A — A Defrilex interpreter uses their personal laptop for VRI sessions. What security concern does this create?','mcq','[\"Personal devices may lack required security controls (encryption, endpoint protection, patch management), creating data exposure risk for client PHI and session content.\"]','[\"No concern - personal devices are fine for remote work.\",\"Personal devices may lack required security controls (encryption, endpoint protection, patch management), creating data exposure risk for client PHI and session content.\",\"It saves the company money.\",\"Personal devices are more secure than company devices.\"]',8,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(178,16,'PART A — What is a vulnerability scan and how often should it be performed?','mcq','[\"An automated assessment of systems and applications for known security weaknesses. Should be performed regularly (at least quarterly, monthly for critical systems) with findings prioritized and remediated.\"]','[\"A scan for computer viruses. Once a year.\",\"An automated assessment of systems and applications for known security weaknesses. Should be performed regularly (at least quarterly, monthly for critical systems) with findings prioritized and remediated.\",\"A background check on employees. At hiring.\",\"A review of financial records. Quarterly.\"]',9,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(179,16,'PART A — What is the purpose of an incident response plan?','mcq','[\"To define a structured, pre-planned process for detecting, containing, eradicating, and recovering from security incidents, minimizing damage and ensuring proper communication and documentation.\"]','[\"To prevent all security incidents from happening.\",\"To define a structured, pre-planned process for detecting, containing, eradicating, and recovering from security incidents, minimizing damage and ensuring proper communication and documentation.\",\"To punish employees who cause incidents.\",\"To satisfy insurance requirements only.\"]',10,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(180,16,'PART B — Scenario: A Defrilex employee reports that their work account was accessed from an unfamiliar location at 3 AM. They were asleep at the time. What is your immediate response?','mcq','[\"Immediately: lock the compromised account, check for data access or exfiltration, review login logs for scope, reset credentials, enable\\/verify MFA, check for lateral movement to other accounts, notify the employee and management, and document the incident.\"]','[\"Change their password and move on.\",\"Immediately: lock the compromised account, check for data access or exfiltration, review login logs for scope, reset credentials, enable\\/verify MFA, check for lateral movement to other accounts, notify the employee and management, and document the incident.\",\"Wait until morning to investigate.\",\"Tell the employee to be more careful.\"]',11,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(181,16,'PART B — Scenario: Defrilex is evaluating a new cloud-based scheduling tool. The vendor says their platform is \'fully secure.\' What should you do before approving the tool?','mcq','[\"Conduct a vendor security assessment: request SOC 2 report, review their data handling policies, confirm BAA capability for PHI, evaluate encryption practices, assess data residency, and verify incident response procedures.\"]','[\"Trust the vendor - they said it is secure.\",\"Conduct a vendor security assessment: request SOC 2 report, review their data handling policies, confirm BAA capability for PHI, evaluate encryption practices, assess data residency, and verify incident response procedures.\",\"Ask for a discount instead.\",\"Check online reviews.\"]',12,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(182,16,'PART B — Scenario: A healthcare client asks Defrilex to provide evidence of its security posture as part of their vendor risk assessment. How should you respond?','mcq','[\"Prepare and provide: security policies, SOC 2 report or equivalent, BAA execution status, encryption practices, employee training records, incident response plan summary, and any relevant compliance certifications. This is standard for regulated-industry vendor relationships.\"]','[\"Tell them your security is fine and they should trust you.\",\"Prepare and provide: security policies, SOC 2 report or equivalent, BAA execution status, encryption practices, employee training records, incident response plan summary, and any relevant compliance certifications. This is standard for regulated-industry vendor relationships.\",\"Refuse - your security practices are proprietary.\",\"Send a generic IT overview.\"]',13,'2026-04-18 06:19:39','2026-04-18 06:19:39'),(183,16,'<h5>Practical Exercise: Incident Response Plan (22 points)</h5>\n<p><strong>Scenario:</strong> A Defrilex employee accidentally sent a spreadsheet containing patient names and appointment details (PHI) to the wrong email address (an external recipient). The employee noticed the mistake 10 minutes after sending.</p>\n<p>Write the <strong>incident response steps</strong> Defrilex should take, <strong>in order</strong>. Include:</p>\n<ul>\n<li>Immediate containment</li>\n<li>Investigation</li>\n<li>Notification requirements</li>\n<li>Remediation</li>\n<li>Prevention measures</li>\n</ul>','long_answer','[]',NULL,14,'2026-04-18 06:19:39','2026-04-18 06:19:39');

